// Email HTML is built directly from user-entered text (task titles,
// descriptions) — escape it so a task containing HTML or a stray link can't
// alter the email's structure in a recipient's mail client.
function escapeHtmlEmail(str) {
  if (!str) return '';
  return String(str).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// Values go into the email HTML escaped, so a name can never add links or formatting to an email that comes from us.
// (A subject line is plain text, not HTML, so it keeps the raw value.) alertsHtml is built here on the server from escaped pieces.
const RAW_HTML_EMAIL_PARAMS = new Set(['alertsHtml', 'ciActionsHtml']);
const SELF_ESCAPING_EMAIL_TEMPLATES = new Set(['taskAssigned']);   // these already escape their own values (escaping twice would show &amp;lt;)
function buildEmail(type, lang, params) {
  const langKey = lang === 'fr' ? 'fr' : 'en';
  const template = EMAIL_TEMPLATES[type][langKey];
  const safe = {};
  for (const [k, v] of Object.entries(params || {})) safe[k] = (typeof v === 'string' && !RAW_HTML_EMAIL_PARAMS.has(k) && !SELF_ESCAPING_EMAIL_TEMPLATES.has(type)) ? escapeHtmlText(v) : v;
  return { subject: String(template(params || {}).subject || '').replace(/[\r\n]+/g, ' '), html: template(safe).html };
}

// ── GOOGLE OAUTH ───────────────────────────────────────────────────────────
// Google sign-in: who is this person, and is it safe to link them to an account?
// 1. Only an email that GOOGLE has verified is trusted (it used to be taken on faith).
// 2. An account made with a password whose email was never verified belongs to nobody yet: someone may have registered another person's
//    address and chosen the password themselves. When the real owner signs in with Google, that unverified account is taken over cleanly:
//    the password, the pending links and the details typed at sign-up are discarded. (Before, the account was handed to them with the
//    stranger's password still working.) An account whose email WAS verified is simply linked, and keeps everything.
// 3. An account already linked to a different Google account is never merged.
// 4. A Google account with no photo, or no family name, can now sign in (it used to crash).
function cleanGoogleName(v, fallback = '') {
  const t = String(v === undefined || v === null ? '' : v).replace(/[<>\u0000-\u001f\u007f]/g, '').replace(/\s+/g, ' ').trim().slice(0, 60);
  return t || fallback;
}
function googleEmailIsVerified(profile) {
  const e = profile && profile.emails && profile.emails[0];
  return !!e && (e.verified === true || e.verified === 'true');
}
async function resolveGoogleUser(profile, attempt = 0) {
  const rawEmail = profile && profile.emails && profile.emails[0] && profile.emails[0].value;
  const email = typeof rawEmail === 'string' ? rawEmail.trim().toLowerCase() : '';
  const googleId = profile && profile.id ? String(profile.id) : '';
  if (!email || !googleId) return { rejected: 'no_email' };
  if (!googleEmailIsVerified(profile)) return { rejected: 'email_not_verified' };

  const display = cleanGoogleName(profile.displayName);
  const given = cleanGoogleName(profile.name && profile.name.givenName), family = cleanGoogleName(profile.name && profile.name.familyName);
  const firstName = given || display.split(' ')[0] || email.split('@')[0].slice(0, 60) || 'User';
  const lastName = family || (given ? '' : display.split(' ').slice(1).join(' ').slice(0, 60));
  const photo = profile.photos && profile.photos[0] && profile.photos[0].value;
  const avatar = typeof photo === 'string' && /^https:\/\//i.test(photo) ? photo.slice(0, 1000) : null;

  const found = (await pool.query(
    'SELECT * FROM users WHERE google_id = $1 OR LOWER(email) = LOWER($2) ORDER BY COALESCE(google_id = $1, false) DESC LIMIT 2', [googleId, email])).rows;
  const linked = found.find(u => u.google_id === googleId);
  if (linked) return { user: linked };                                   // already this Google account (even if their Google email has since changed)
  const byEmail = found.find(u => String(u.email).toLowerCase() === email);

  if (!byEmail) {
    const insert = await pool.query(
      `INSERT INTO users (email, google_id, first_name, last_name, avatar_url, email_verified, plan, plan_started_at, plan_expires_at)
       VALUES ($1, $2, $3, $4, $5, true, 'free', NOW(), NOW() + INTERVAL '${TRIAL_DAYS} days') RETURNING *`,
      [email, googleId, firstName, lastName, avatar]);
    return { user: insert.rows[0], created: true };
  }
  if (byEmail.google_id && byEmail.google_id !== googleId) return { rejected: 'account_conflict' };

  if (byEmail.email_verified) {                                          // the owner already proved this address: link, change nothing else
    const up = await pool.query('UPDATE users SET google_id = $1, avatar_url = COALESCE($2, avatar_url) WHERE id = $3 RETURNING *', [googleId, avatar, byEmail.id]);
    return { user: up.rows[0], linked: true };
  }
  // Never verified: take it over cleanly. The guard on email_verified means this only ever touches an account nobody has proved they own.
  const reclaimed = await pool.query(
    `UPDATE users SET google_id = $1, avatar_url = $2, email_verified = true, password_hash = NULL,
       verification_token = NULL, verification_expires = NULL, reset_token = NULL, reset_expires = NULL,
       first_name = $3, last_name = $4, phone = NULL, country = NULL, token_version = token_version + 1, updated_at = NOW()
     WHERE id = $5 AND email_verified = false RETURNING *`, [googleId, avatar, firstName, lastName, byEmail.id]);
  if (reclaimed.rows.length) { console.warn('Google sign-in reclaimed an unverified account (its password was discarded):', byEmail.id); return { user: reclaimed.rows[0], reclaimed: true }; }
  // It was verified a moment ago by someone else: look again (once) and link normally
  return attempt < 1 ? resolveGoogleUser(profile, attempt + 1) : { rejected: 'try_again' };
}
async function googleStrategyVerify(accessToken, refreshToken, profile, done) {
  try {
    const out = await resolveGoogleUser(profile);
    if (out.rejected) { console.warn('Google sign-in refused:', out.rejected); return done(null, false); }   // the sign-in page then shows its usual "Google sign-in failed"
    return done(null, out.user);
  } catch (e) { return done(e, null); }
}
passport.use(new GoogleStrategy({
  clientID: process.env.GOOGLE_CLIENT_ID,
  clientSecret: process.env.GOOGLE_CLIENT_SECRET,
  callbackURL: `${BASE_URL}/auth/google/callback`
}, googleStrategyVerify));

passport.serializeUser((user, done) => done(null, user.id));
// The app signs people in with its own cookie (see authRequired), not with this session. The session only carries the
// Google sign-in from the redirect to the callback, where req.user is set straight from the sign-in step. Looking the user
// up again on every later request was a database read for nothing — and with the database unreachable it failed every
// page for anyone still holding the session cookie.
passport.deserializeUser((id, done) => done(null, { id }));

// ── AUTH MIDDLEWARE ────────────────────────────────────────────────────────
async function authRequired(req, res, next) {
  const token = req.cookies.arreyon_token || req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'Authentication required' });
  let decoded;
  try { decoded = jwt.verify(token, JWT_SECRET); } catch (e) { return res.status(401).json({ error: 'Invalid or expired token' }); }
  // Only a real sign-in counts: not an admin/board token, and not a short-lived connection "state" token
  if (!decoded || !decoded.userId || isStateToken(decoded)) return res.status(401).json({ error: 'Invalid or expired token' });
  try {
    const v = await currentTokenVersion('users', decoded.userId);
    if (v === null) return res.status(401).json({ error: 'Invalid or expired token' });   // the account no longer exists
    if ((Number(decoded.tv) || 0) !== v) return res.status(401).json({ error: 'Your session has ended. Please sign in again.', code: 'session_ended' });
  } catch (e) { return res.status(500).json({ error: 'Could not check your session. Please try again.' }); }
  req.userId = decoded.userId;
  req.userPlan = decoded.plan;
  next();
}

// ── Team accounts: resolve the EFFECTIVE account for plan/limits purposes ──
// A team member has their own login, but their plan tier, consultation usage,
// director access, and feature gating (Financial Tools, downloads, etc.) all
// come from the OWNER's account, not their own — they're operating inside a
// shared account, not a separate subscription. req.userId always stays the
// actual logged-in person (for attribution); req.accountId/req.account are
// the resolved owner-or-self record everything else should check against.
async function resolveAccount(userId) {
  const result = await pool.query('SELECT * FROM users WHERE id = $1', [userId]);
  const user = result.rows[0];
  if (!user) return null;

  let account = user;
  if (user.team_owner_id) {
    const ownerResult = await pool.query('SELECT * FROM users WHERE id = $1', [user.team_owner_id]);
    if (ownerResult.rows[0]) account = ownerResult.rows[0];
  }

  // Subscription lifecycle enforcement — checked on the RESOLVED account
  // (the owner, for team members), since a team member inherits the
  // owner's plan entirely and should see the same locked state if the
  // owner's subscription lapses, not their own separate (nonexistent)
  // expiry. A lapsed free trial or paid subscription moves to an explicit
  // 'expired' state rather than silently reverting to starter, so the
  // frontend can show a real "subscribe to continue" lockout instead of
  // quietly treating expiration as equivalent to the free tier.
  if (account.plan !== 'expired' && account.plan_expires_at && new Date(account.plan_expires_at) < new Date()) {
    // previous_plan lets the lockout say "renew your Pro plan" (paid) rather than "upgrade" (free trial).
    const updated = await pool.query(
      `UPDATE users SET previous_plan = plan, plan = 'expired', updated_at = NOW() WHERE id = $1 RETURNING *`,
      [account.id]
    );
    account = updated.rows[0];
  }

  return account;
}

// ═══════════════════════════════════════════════════════════════════════════
// PLANS v2 — database-backed helpers and the plan gate middleware.
// <PLAN-DB-START>
// ═══════════════════════════════════════════════════════════════════════════

// ── Pricing configuration (editable from admin; cached briefly) ─────────────
let pricingCache = { at: 0, cfg: null };
let pricingLastGood = null;   // the last prices that were read successfully from the database
function defaultPricingConfig() {
  const plans = {};
  for (const k of PAID_PLANS) plans[k] = { usd: DEFAULT_PLAN_PRICES_USD[k], cfa: null };
  return { rate: DEFAULT_FCFA_RATE, discount: DEFAULT_ANNUAL_DISCOUNT, plans };
}
async function loadPricingConfig(force = false) {
  if (!force && pricingCache.cfg && Date.now() - pricingCache.at < 60 * 1000) return pricingCache.cfg;
  const cfg = defaultPricingConfig();
  let readOk = false;
  try {
    const [settings, rows] = await Promise.all([
      pool.query(`SELECT key, value FROM app_settings WHERE key IN ('fcfa_rate', 'annual_discount_percent')`),
      pool.query(`SELECT plan_key, usd_monthly, cfa_monthly FROM plan_pricing`)
    ]);
    for (const s of settings.rows) {
      if (s.key === 'fcfa_rate' && Number(s.value) > 0) cfg.rate = Number(s.value);
      if (s.key === 'annual_discount_percent' && Number(s.value) >= 0) cfg.discount = Number(s.value);
    }
    for (const r of rows.rows) {
      if (cfg.plans[r.plan_key]) cfg.plans[r.plan_key] = { usd: Number(r.usd_monthly), cfa: r.cfa_monthly === null ? null : Number(r.cfa_monthly) };
    }
    readOk = true;
  } catch (e) {
    // The database could not be read. If prices were read successfully before, THOSE are kept (the built-in defaults are not
    // your prices, and must never be shown or charged just because the database was briefly out); the next try is in ~10 seconds.
    const kept = (typeof pricingLastGood !== 'undefined') ? pricingLastGood : null;
    if (kept) {
      console.error('loadPricingConfig kept the last known prices:', e.message);
      pricingCache = { at: Date.now() - 50 * 1000, cfg: kept };
      return kept;
    }
    // If the pricing tables are not there yet, the defaults above are used rather than failing every page.
    console.error('loadPricingConfig fell back to defaults:', e.message);
  }
  if (readOk && typeof pricingLastGood !== 'undefined') pricingLastGood = cfg;
  pricingCache = { at: Date.now(), cfg };
  return cfg;
}

// ── Connected sites (WordPress and Shopify count the same) ──────────────────
async function siteRowsOldestFirst(accountId) {
  const r = await pool.query(
    `SELECT wc.business_id, wc.connected_at, 'wordpress' AS platform
       FROM website_connections wc JOIN businesses b ON b.id = wc.business_id
      WHERE b.user_id = $1 AND wc.connection_status <> 'disconnected'
     UNION ALL
     SELECT sc.business_id, sc.connected_at, 'shopify' AS platform
       FROM shopify_connections sc JOIN businesses b ON b.id = sc.business_id
      WHERE b.user_id = $1 AND sc.connection_status <> 'disconnected'
     ORDER BY connected_at ASC NULLS LAST`,
    [accountId]
  );
  return r.rows;
}
async function countAccountSites(accountId, excludeBusinessId = null) {
  const rows = await siteRowsOldestFirst(accountId);
  return rows.filter(r => r.business_id !== excludeBusinessId).length;
}
// After a downgrade (or an admin change) an account can hold more sites than its
// plan allows: the oldest ones stay active, the rest are paused until the person
// upgrades or disconnects one.
async function pausedBusinessIds(account) {
  const limit = websitePlanFor(account.plan).sites;
  const rows = await siteRowsOldestFirst(account.id);
  if (rows.length <= limit) return [];
  const allowed = new Set(rows.slice(0, limit).map(r => r.business_id));
  return [...new Set(rows.slice(limit).map(r => r.business_id).filter(id => !allowed.has(id)))];
}

// ── Blog post quota ─────────────────────────────────────────────────────────
// Counted from a usage log (not from the posts themselves) so deleting a draft
// can never hand the allowance back.
async function postsUsedInPeriod(account) {
  const cfg = websitePlanFor(account.plan);
  const r = cfg.postsPeriod === 'trial'
    ? await pool.query(`SELECT COUNT(*)::int AS n FROM website_post_usage WHERE account_id = $1 AND created_at >= $2`, [account.id, account.plan_started_at || new Date(0)])
    : await pool.query(`SELECT COUNT(*)::int AS n FROM website_post_usage WHERE account_id = $1 AND created_at >= date_trunc('month', NOW())`, [account.id]);
  return r.rows[0].n;
}
async function checkPostQuota(account) {
  const cfg = websitePlanFor(account.plan);
  const used = await postsUsedInPeriod(account);
  return { ok: used < cfg.posts, used, limit: cfg.posts, period: cfg.postsPeriod };
}
function postQuotaMessage(plan, q) {
  if (q.period === 'trial') return `Limit reached: you've used your ${q.limit} free blog posts. Upgrade to Arreyon Starter or above to keep generating posts.`;
  return `Limit reached: you've used all ${q.limit} blog posts included in ${PLAN_NAMES[plan] || 'your plan'} this month. Upgrade for more, or try again next month.`;
}
async function checkPostQuotaForBusiness(businessId) {
  const b = await pool.query('SELECT user_id FROM businesses WHERE id = $1', [businessId]);
  if (!b.rows.length) return { ok: false, message: 'This business no longer exists.' };
  const account = await resolveAccount(b.rows[0].user_id);
  if (!account || account.plan === 'expired') return { ok: false, message: 'Your plan has expired. Renew or upgrade to keep generating posts.' };
  const q = await checkPostQuota(account);
  return q.ok ? { ok: true, account, quota: q } : { ok: false, message: postQuotaMessage(account.plan, q), quota: q };
}
async function recordPostUsage(accountId, businessId, platform) {
  try {
    await pool.query('INSERT INTO website_post_usage (account_id, business_id, platform) VALUES ($1, $2, $3)', [accountId, businessId, platform]);
  } catch (e) { console.error('recordPostUsage failed:', e.message); }
}

// ── Background work (agent cycles, scheduled posts) respects the owner's plan ──
async function ownerPlanKey(userId) {
  const a = await resolveAccount(userId);
  return a ? a.plan : 'expired';
}
async function backgroundAccessFor(ownerUserId, businessId, feature) {
  const account = await resolveAccount(ownerUserId);
  if (!account || account.plan === 'expired') return { ok: false, message: 'Skipped: your plan has expired. Renew or upgrade to resume this.' };
  if (!planHasWebsiteFeature(account.plan, feature)) return { ok: false, message: `Skipped: this is available on ${PLAN_NAMES[minPlanForWebsiteFeature(feature)]} and above.` };
  const paused = await pausedBusinessIds(account);
  if (paused.includes(businessId)) return { ok: false, message: `Skipped: this website is paused because ${PLAN_NAMES[account.plan]} includes ${websitePlanFor(account.plan).sites} connected website${websitePlanFor(account.plan).sites === 1 ? '' : 's'}.` };
  return { ok: true, account };
}

// ── What the frontend needs to know about this account ──────────────────────
async function buildAccessInfo(account) {
  const plan = account.plan;
  const wp = websitePlanFor(plan);
  const steps = agentStepsForPlan(plan);
  let sitesUsed = 0, postsUsed = 0, paused = [];
  try {
    [sitesUsed, postsUsed, paused] = await Promise.all([countAccountSites(account.id), postsUsedInPeriod(account), pausedBusinessIds(account)]);
  } catch (e) { console.error('buildAccessInfo counts failed:', e.message); }
  const previous = account.previous_plan || null;
  return {
    plan, previousPlan: previous,
    locked: plan === 'expired',
    lockReason: plan === 'expired' ? lockReasonFor(previous) : null,
    websiteOnly: plan === 'auto_seo',
    trialDays: TRIAL_DAYS,
    website: { sites: wp.sites, sitesUsed, posts: wp.posts, postsUsed, postsPeriod: wp.postsPeriod, features: wp.features, pausedBusinessIds: paused },
    agentSteps: steps === null ? 'all' : Array.from(steps),
    // Which plan first unlocks each website feature, so the dashboard can say "available on Pro" without keeping its own copy of the tiers.
    featureMinPlan: Object.fromEntries(WEBSITE_FULL_FEATURES.map(f => [f, minPlanForWebsiteFeature(f)]))
  };
}

// ── The plan gate ───────────────────────────────────────────────────────────
// Runs before every API route. Expired accounts keep only their account pages;
// Auto SEO accounts keep only the website tool; everyone's website-tool access
// follows their plan. Public routes and admin routes are left alone.
const PLAN_GATE_SKIP = [/^\/api\/auth\//, /^\/api\/admin\//, /^\/api\/cms/, /^\/api\/announcements$/, /^\/api\/website-tools\//, /^\/api\/website-connector\//, /^\/api\/plans\//, /^\/api\/share\//];
const gateAccountCache = new Map();   // userId -> { at, account }  (5 seconds: the dashboard fires many calls at once)
async function gateAccountFor(userId) {
  const hit = gateAccountCache.get(userId);
  if (hit && Date.now() - hit.at < 5000) return hit.account;
  const account = await resolveAccount(userId);
  if (gateAccountCache.size > 5000) gateAccountCache.clear();
  gateAccountCache.set(userId, { at: Date.now(), account });
  return account;
}
function planDenyPayload(account, d) {
  return {
    error: d.message, code: d.code,
    locked: d.code === 'expired' || d.code === 'plan_scope',
    lockReason: d.lockReason || null,
    upgradeRequired: d.code === 'feature' || d.code === 'site_limit' || d.code === 'post_limit',
    requiredPlan: d.requiredPlan || null, feature: d.feature || null,
    plan: account.plan, previousPlan: account.previous_plan || null,
    ...(d.extra || {})
  };
}
async function planGate(req, res, next) {
  try {
    const path = req.path;
    if (!path.startsWith('/api/') || PLAN_GATE_SKIP.some(re => re.test(path))) return next();
    const token = req.cookies?.arreyon_token || (req.headers.authorization || '').replace('Bearer ', '');
    if (!token) return next();                       // the route's own sign-in check answers this
    let decoded;
    try { decoded = jwt.verify(token, JWT_SECRET); } catch (e) { return next(); }
    if (!decoded || !decoded.userId) return next();
    const account = await gateAccountFor(decoded.userId);
    if (!account) return next();
    req.planAccount = account;

    const decision = decidePlanAccess({ plan: account.plan, method: req.method, path, body: req.body, previousPlan: account.previous_plan });
    if (!decision.allow) return res.status(403).json(planDenyPayload(account, decision));

    const needs = decision.needs || {};
    if (needs.newSite || needs.connectSite || needs.postQuota || needs.checkPaused) {
      const bizMatch = path.match(/^\/api\/business\/([0-9a-fA-F-]{36})\//);
      const pathBizId = bizMatch ? bizMatch[1] : null;
      const wp = websitePlanFor(account.plan);

      if (needs.newSite || needs.connectSite) {
        const used = await countAccountSites(account.id, needs.connectSite ? pathBizId : null);
        if (used >= wp.sites) {
          return res.status(403).json(planDenyPayload(account, {
            code: 'site_limit',
            message: `${PLAN_NAMES[account.plan]} includes ${wp.sites} connected website${wp.sites === 1 ? '' : 's'}. Disconnect one, or upgrade, to connect another.`,
            extra: { limit: wp.sites, used }
          }));
        }
      }
      if (needs.postQuota) {
        const q = await checkPostQuota(account);
        if (!q.ok) {
          return res.status(403).json(planDenyPayload(account, { code: 'post_limit', message: postQuotaMessage(account.plan, q), extra: { limit: q.limit, used: q.used, period: q.period } }));
        }
      }
      if (needs.checkPaused && pathBizId) {
        const paused = await pausedBusinessIds(account);
        if (paused.includes(pathBizId)) {
          return res.status(403).json(planDenyPayload(account, {
            code: 'site_paused',
            message: `This website is paused because ${PLAN_NAMES[account.plan]} includes ${wp.sites} connected website${wp.sites === 1 ? '' : 's'}. Upgrade, or disconnect another site, to resume it.`,
            extra: { limit: wp.sites }
          }));
        }
      }
    }
    next();
  } catch (e) {
    // A fault in the gate itself must never take the whole app down; the route's own checks still apply.
    console.error('planGate error (request allowed through):', e.message);
    next();
  }
}
app.use(planGate);
// <PLAN-DB-END>

// Real, deliberate single, shared resolution — a business's real site URL
// genuinely can come from three different real places (a manually entered
// profile field, a connected WordPress site, a connected Shopify store),
// and every real feature that needs "this business's real site" should
// resolve it the exact same real way, rather than each place quietly
// re-implementing its own, inevitably inconsistent fallback.
async function resolveBusinessSiteUrl(businessId, businessWebsiteField) {
  if (businessWebsiteField) return businessWebsiteField;
  // Each platform says whether this business has a site of its own there; the first that does wins.
  for (const agent of Object.values(WEBSITE_AGENTS)) {
    const url = await agent.siteUrl(businessId);
    if (url) return url;
  }
  return null;
}

// ═══════════════════════════════════════════════════════════════════════════
// BUSINESS WORKSPACE — Phase 1, Step 3
// A single place that assembles whatever's known about a business, so future
// AI features read from here instead of each separately re-fetching (or
// re-asking the user for) the same context. Deliberately returns RAW English
// data with no translation-on-read — that's a presentation-layer concern for
// whichever feature displays it, not something baked into a shared data
// helper multiple future callers will depend on.
//
// Ownership is checked INSIDE this function (against the resolved account),
// not left to the caller to remember — every future consumer of this helper
// gets that protection automatically.
//
// Honest current limitation: there is no persisted financial-calculation
// history table (Financial Tools calculations are ephemeral, computed
// client-side and never saved), so no financial history is included yet.
// This will need its own schema work in a later phase, not invented here.
// ═══════════════════════════════════════════════════════════════════════════
async function getBusinessContext(businessId, accountId) {
  const bizResult = await pool.query('SELECT * FROM businesses WHERE id = $1 AND user_id = $2', [businessId, accountId]);
  if (!bizResult.rows.length) return null;
  const business = bizResult.rows[0];

  const factsResult = await pool.query(
    `SELECT DISTINCT ON (fact_key) fact_key, fact_value, source_type, created_at
     FROM business_facts WHERE business_id = $1 ORDER BY fact_key, created_at DESC`,
    [businessId]
  );

  const researchResult = await pool.query(
    `SELECT structured_data, verification_data, scope, created_at FROM research_sessions
     WHERE business_id = $1 AND structured_data IS NOT NULL ORDER BY created_at DESC LIMIT 1`,
    [businessId]
  );

  const entrepreneurResult = await pool.query(
    `SELECT id, mode, research_backed, business_plan IS NOT NULL AS has_business_plan, created_at
     FROM entrepreneur_sessions WHERE business_id = $1 ORDER BY created_at DESC LIMIT 10`,
    [businessId]
  );

  return {
    business: {
      id: business.id, name: business.name, website: business.website, industry: business.industry,
      country: business.country, region: business.region, city: business.city, currency: business.currency,
      businessModel: business.business_model, stage: business.stage,
      goals: business.goals, challenges: business.challenges, opportunities: business.opportunities,
      strategySummary: business.strategy_summary
    },
    facts: factsResult.rows,
    latestResearch: researchResult.rows[0] || null,
    entrepreneurSessions: entrepreneurResult.rows,
    financialHistory: null // not yet available — see function comment above
  };
}

// Proof-of-concept endpoint for Step 3 — exercises getBusinessContext() in
// isolation. Nothing else in the application calls this yet; it exists so
// the helper can be verified against real data before Step 4 wires any
// actual feature to it.
app.get('/api/business/:id/workspace-context', authRequired, async (req, res) => {
  try {
    const account = await resolveAccount(req.userId);
    const context = await getBusinessContext(req.params.id, account.id);
    if (!context) return res.status(404).json({ error: 'Business not found' });
    res.json(context);
  } catch (e) {
    console.error('Workspace context error:', e.message);
    res.status(500).json({ error: 'Failed to load business context' });
  }
});

// Condenses a full business context into a short paragraph suitable for
// appending to an AI persona — deliberately brief (a few sentences, not a
// JSON dump) since this gets re-sent on every single chat turn in an active
// conversation, and token cost compounds quickly in a multi-turn session.
function summarizeBusinessContextForAI(context) {
  if (!context) return '';
  const b = context.business;
  const parts = [];
  parts.push(`${b.name || 'This business'}${b.industry ? ', a ' + b.industry + ' business' : ''}${b.city || b.country ? ' based in ' + [b.city, b.country].filter(Boolean).join(', ') : ''}.`);
  if (context.facts.length) {
    const topFacts = context.facts.slice(0, 3).map(f => f.fact_value).filter(Boolean);
    if (topFacts.length) parts.push(`Known about the business: ${topFacts.join('; ')}.`);
  }
  if (context.latestResearch) parts.push(`Market research has already been done for this business — you don't need to guess at their competitive landscape from scratch.`);
  if (b.challenges && b.challenges.length) parts.push(`Stated challenges: ${b.challenges.join(', ')}.`);
  if (b.goals && b.goals.length) parts.push(`Stated goals: ${JSON.stringify(b.goals)}.`);
  if (!parts.length) return '';
  return `\n\nBUSINESS CONTEXT (use this naturally — the founder shouldn't need to re-explain their business to you): ${parts.join(' ')}`;
}

// ═══════════════════════════════════════════════════════════════════════════
// BUSINESS INTELLIGENCE — Phase 2, Step 1
// A deterministic score measuring how much is actually known and documented
// about a business — NOT a qualitative "how healthy is this business"
// judgment. That distinction matters: this number is 100% computed from data
// presence, fully explainable via its breakdown, and can never be an AI
// hallucination masquerading as fact. A qualitative AI-inferred assessment
// (SWOT) is a separate, clearly-labeled concept — see Step 2.
// ═══════════════════════════════════════════════════════════════════════════
function computeBusinessCompletenessScore(context) {
  const b = context.business;
  const breakdown = {};

  const coreFields = [b.name, b.industry, b.country, b.businessModel, b.stage];
  const coreFilled = coreFields.filter(Boolean).length;
  breakdown.coreIdentity = { points: coreFilled * 4, max: 20, detail: `${coreFilled}/5 core fields filled` };

  const factCount = context.facts.length;
  const factPoints = Math.min(factCount, 10) * 2.5;
  breakdown.businessFacts = { points: Math.round(factPoints), max: 25, detail: `${factCount} fact${factCount === 1 ? '' : 's'} documented` };

  breakdown.marketResearch = { points: context.latestResearch ? 20 : 0, max: 20, detail: context.latestResearch ? 'Research on file' : 'No research yet' };

  breakdown.entrepreneurEngagement = { points: context.entrepreneurSessions.length ? 15 : 0, max: 15, detail: context.entrepreneurSessions.length ? `${context.entrepreneurSessions.length} session(s) linked` : 'No linked sessions' };

  const strategicFields = [b.goals?.length > 0, b.challenges?.length > 0, b.opportunities?.length > 0, !!b.strategySummary];
  const strategicFilled = strategicFields.filter(Boolean).length;
  breakdown.strategicPlanning = { points: strategicFilled * 5, max: 20, detail: `${strategicFilled}/4 strategic fields filled` };

  const score = Math.round(Object.values(breakdown).reduce((sum, v) => sum + v.points, 0));
  return { score, breakdown };
}

// Deterministic funding readiness score — built entirely from objective,
// verifiable signals already tracked elsewhere in the platform (has a plan,
// has verified financials, tracks growth over time, etc.), never an
// AI-invented number. Profile completeness reuses the existing Phase 2
// score rather than a separate calculation.
function computeFundingReadinessScore({
  hasBusinessPlan,
  hasVerifiedFinancials,
  hasGrowthTracking,
  hasBusinessIntelligence,
  hasMarketContext,
  trackedCompetitorCount,
  profileCompletenessPct
}) {
  let score = 0;
  const breakdown = [];
  const add = (points, key, met) => {
    if (met) score += points;
    breakdown.push({ key, points: met ? points : 0, maxPoints: points, met: !!met });
  };

  add(20, 'has_business_plan', hasBusinessPlan);
  add(20, 'has_verified_financials', hasVerifiedFinancials);
  add(15, 'has_growth_tracking', hasGrowthTracking);
  add(15, 'has_business_intelligence', hasBusinessIntelligence);
  add(10, 'has_market_context', hasMarketContext);
  add(10, 'has_tracked_competitor', trackedCompetitorCount > 0);

  const profilePoints = Math.round((profileCompletenessPct / 100) * 10);
  score += profilePoints;
  breakdown.push({ key: 'profile_completeness', points: profilePoints, maxPoints: 10, met: profileCompletenessPct >= 80 });

  return { score: Math.min(score, 100), breakdown };
}

// Proof-of-concept endpoint, isolated from any real feature — same pattern
// used for getBusinessContext() in Phase 1. Nothing else calls this yet.
app.get('/api/business/:id/completeness-score', authRequired, async (req, res) => {
  try {
    const account = await resolveAccount(req.userId);
    const context = await getBusinessContext(req.params.id, account.id);
    if (!context) return res.status(404).json({ error: 'Business not found' });
    res.json(computeBusinessCompletenessScore(context));
  } catch (e) {
    console.error('Completeness score error:', e.message);
    res.status(500).json({ error: 'Failed to compute completeness score' });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// BUSINESS INTELLIGENCE — Phase 2, Step 2
// Qualitative, AI-INFERRED analysis — genuinely different in kind from
// Step 1's deterministic score, and must always be presented as such (an
// "AI-inferred" label, never as verified fact — see the AI Trust
// Architecture principle in the Phase 0 audit). Grounded in the same
// getBusinessContext() used everywhere else, so this reflects actual known
// facts rather than generic business-advice platitudes.
// ═══════════════════════════════════════════════════════════════════════════
app.post('/api/business/:id/intelligence', authRequired, async (req, res) => {
  const language = req.body?.language === 'fr' ? 'fr' : 'en';
  try {
    const account = await resolveAccount(req.userId);
    const context = await getBusinessContext(req.params.id, account.id);
    if (!context) return res.status(404).json({ error: 'Business not found' });

    const completeness = computeBusinessCompletenessScore(context);
    const contextSummary = summarizeBusinessContextForAI(context) || 'No detailed context is available for this business yet.';

    const prompt = `You are a business intelligence analyst. Based on everything actually known about this business, provide a grounded, specific qualitative analysis — not generic business advice that could apply to any business.
${contextSummary}

DATA COMPLETENESS: ${completeness.score}/100. ${completeness.score < 40 ? 'This is LOW — be explicitly humble and tentative in your analysis rather than inventing specifics the data does not support.' : 'Use this as a general sense of how much is actually known.'}

Return ONLY valid JSON, no markdown, in exactly this structure:
{
  "strengths": ["specific strength grounded in what's actually known, or state there isn't enough data for this yet"],
  "weaknesses": ["..."],
  "opportunities": ["..."],
  "threats": ["..."],
  "critical_bottleneck": "the single most limiting factor right now, one sentence — or state that there isn't enough data to identify one confidently",
  "priority_problems": ["the 2-3 most urgent problems to address, in order"],
  "opportunity_score": "high|medium|low",
  "competitive_position": "strong|moderate|weak|unclear",
  "growth_readiness": "high|medium|low",
  "confidence_note": "one honest sentence about how much this analysis can be trusted given the data actually available"
}`;

    const raw = await callAI({ persona: prompt + frenchInstruction(language, { jsonMode: true }), messages: [{ role: 'user', content: 'Provide the analysis now, as JSON only.' }], complexity: 'complex', context: { feature: 'business_intelligence', userId: req.userId }, maxTokens: 2000 });

    let intelligence;
    try {
      intelligence = extractJSON(raw);
    } catch (e) {
      console.error('Business intelligence JSON parse failed. Length:', e.message, '| Response length:', raw.length, '| Last 300 chars:', raw.slice(-300));
      throw new Error('Could not generate business intelligence — please try again');
    }
    for (const field of ['strengths', 'weaknesses', 'opportunities', 'threats', 'priority_problems']) {
      if (!Array.isArray(intelligence[field])) {
        console.error(`Business intelligence field "${field}" was not an array:`, typeof intelligence[field]);
        throw new Error('Could not generate business intelligence — please try again');
      }
    }

    await pool.query(
      'UPDATE businesses SET intelligence_snapshot = $1, intelligence_snapshot_fr = NULL, intelligence_generated_at = NOW() WHERE id = $2',
      [JSON.stringify(intelligence), req.params.id]
    );

    res.json({ intelligence, completeness, generatedAt: new Date().toISOString() });
  } catch (err) {
    console.error('Business intelligence error:', err.message);
    res.status(500).json({ error: safeErrorMessage(err, 'Failed to generate business intelligence. Please try again.') });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// BUSINESS X-RAY — Phase 2 completion (consolidates BI-01, BI-04, BX-01, BX-02)
// Same pattern as Business Intelligence above: qualitative-turned-numeric,
// AI-ASSESSED per axis (never presented as verified fact), grounded in the
// same getBusinessContext(). The overall health score is NOT asked of the
// AI — it's computed deterministically as the average of the 8 AI-assessed
// axes, so it can never disagree with the breakdown it's summarizing.
// ═══════════════════════════════════════════════════════════════════════════
const XRAY_AXES = ['strategy', 'marketing', 'sales', 'finance', 'operations', 'customer_experience', 'brand', 'digital'];

function computeXRayOverall(scores) {
  const values = XRAY_AXES.map(axis => {
    const v = Number(scores?.[axis]);
    return Number.isFinite(v) ? Math.max(0, Math.min(100, v)) : null;
  }).filter(v => v !== null);
  if (!values.length) return null;
  return Math.round(values.reduce((sum, v) => sum + v, 0) / values.length);
}

app.post('/api/business/:id/business-xray', authRequired, async (req, res) => {
  const language = req.body?.language === 'fr' ? 'fr' : 'en';
  try {
    const account = await resolveAccount(req.userId);
    const context = await getBusinessContext(req.params.id, account.id);
    if (!context) return res.status(404).json({ error: 'Business not found' });

    const completeness = computeBusinessCompletenessScore(context);
    const contextSummary = summarizeBusinessContextForAI(context) || 'No detailed context is available for this business yet.';

    const prompt = `You are a business diagnostics analyst. Based on everything actually known about this business, score it across 8 specific dimensions and identify the single biggest bottleneck holding it back.
${contextSummary}

DATA COMPLETENESS: ${completeness.score}/100. ${completeness.score < 40 ? 'This is LOW — be explicitly conservative with scores rather than inventing confidence the data does not support. Scores in the 40-60 range reflect genuine uncertainty, not necessarily mediocre performance.' : 'Use this as a general sense of how much is actually known.'}

Score each dimension 0-100, where 0 is critically weak/nonexistent and 100 is excellent and fully optimized. Base every score on what is actually known — do not default to a "safe middle" score out of caution; a genuinely strong or weak area should be scored accordingly.

Return ONLY valid JSON, no markdown, in exactly this structure:
{
  "scores": {
    "strategy": 0-100,
    "marketing": 0-100,
    "sales": 0-100,
    "finance": 0-100,
    "operations": 0-100,
    "customer_experience": 0-100,
    "brand": 0-100,
    "digital": 0-100
  },
  "axis_notes": {
    "strategy": "one sentence justifying this score",
    "marketing": "...",
    "sales": "...",
    "finance": "...",
    "operations": "...",
    "customer_experience": "...",
    "brand": "...",
    "digital": "..."
  },
  "bottleneck_axis": "the single axis name above that is most limiting the business right now",
  "bottleneck_reasoning": "2-3 sentences on why this is the primary bottleneck and what fixing it would unlock",
  "confidence_note": "one honest sentence about how much this assessment can be trusted given the data actually available"
}`;

    const raw = await callAI({ persona: prompt + frenchInstruction(language, { jsonMode: true }), messages: [{ role: 'user', content: 'Provide the Business X-Ray now, as JSON only.' }], complexity: 'complex', context: { feature: 'business_xray', userId: req.userId }, maxTokens: 2200 });

    let xray;
    try {
      xray = extractJSON(raw);
    } catch (e) {
      console.error('Business X-Ray JSON parse failed. Length:', e.message, '| Response length:', raw.length, '| Last 300 chars:', raw.slice(-300));
      throw new Error('Could not generate Business X-Ray — please try again');
    }
    if (!xray.scores || typeof xray.scores !== 'object') {
      console.error('Business X-Ray missing scores object');
      throw new Error('Could not generate Business X-Ray — please try again');
    }
    for (const axis of XRAY_AXES) {
      if (typeof xray.scores[axis] !== 'number') {
        console.error(`Business X-Ray axis "${axis}" was not a number:`, typeof xray.scores[axis]);
        throw new Error('Could not generate Business X-Ray — please try again');
      }
    }
    if (!XRAY_AXES.includes(xray.bottleneck_axis)) {
      console.error('Business X-Ray bottleneck_axis was not a recognized axis:', xray.bottleneck_axis);
      throw new Error('Could not generate Business X-Ray — please try again');
    }

    const overallHealthScore = computeXRayOverall(xray.scores);
    const businessXray = { ...xray, overall_health_score: overallHealthScore };

    await pool.query(
      'UPDATE businesses SET business_xray = $1, business_xray_fr = NULL, business_xray_generated_at = NOW() WHERE id = $2',
      [JSON.stringify(businessXray), req.params.id]
    );

    res.json({ businessXray, completeness, generatedAt: new Date().toISOString() });
  } catch (err) {
    console.error('Business X-Ray error:', err.message);
    res.status(500).json({ error: safeErrorMessage(err, 'Failed to generate Business X-Ray. Please try again.') });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// GROWTH CENTER — Phase 3, Step 1
// Deterministic progress tracking, same trust principle as the Financial
// Tools and Business Intelligence completeness score — this number is never
// AI-estimated, it's plain math against real user-reported figures.
// ═══════════════════════════════════════════════════════════════════════════
function computeGrowthProgress(startingValue, currentValue, targetValue) {
  if (targetValue === startingValue) return null; // no actual change was requested — can't compute a meaningful percentage
  const raw = (currentValue - startingValue) / (targetValue - startingValue);
  return { pct: Math.max(0, Math.min(100, Math.round(raw * 100))), rawPct: Math.round(raw * 100) };
}

// Creating a new objective retires any existing active one for this business
// — a business has one active Growth Objective at a time in this first
// version, keeping the concept simple rather than juggling several at once.
app.post('/api/business/:id/growth-objective', authRequired, async (req, res) => {
  const { metricName, unit, startingValue, targetValue, targetDate } = req.body;
  if (!metricName || startingValue === undefined || targetValue === undefined) {
    return res.status(400).json({ error: 'Please provide a metric name, starting value, and target value.' });
  }
  const startNum = parseFloat(startingValue), targetNum = parseFloat(targetValue);
  if (isNaN(startNum) || isNaN(targetNum)) return res.status(400).json({ error: 'Starting and target values must be numbers.' });
  if (startNum === targetNum) return res.status(400).json({ error: 'Target value must be different from the starting value.' });

  try {
    const account = await resolveAccount(req.userId);
    const biz = await pool.query('SELECT id FROM businesses WHERE id = $1 AND user_id = $2', [req.params.id, account.id]);
    if (!biz.rows.length) return res.status(404).json({ error: 'Business not found' });

    const inserted = await pool.query(
      `INSERT INTO growth_objectives (business_id, owner_id, metric_name, unit, starting_value, current_value, target_value, target_date)
       VALUES ($1, $2, $3, $4, $5, $5, $6, $7) RETURNING *`,
      [req.params.id, account.id, metricName, unit || null, startNum, targetNum, targetDate || null]
    );
    await pool.query('INSERT INTO growth_progress_history (objective_id, value) VALUES ($1, $2)', [inserted.rows[0].id, startNum]);

    res.json({ success: true, objective: inserted.rows[0], progress: computeGrowthProgress(startNum, startNum, targetNum) });
  } catch (e) {
    console.error('Create growth objective error:', e.message);
    res.status(500).json({ error: 'Failed to create growth objective' });
  }
});

// Lists every active goal for a business — the new entry point now that a
