// ═══════════════════════════════════════════════════════════════════════════
// PHASE 8 — BUSINESS PLAN + FUNDING (Step 2: Funding Readiness Score)
// The score is deterministic (computeFundingReadinessScore, computed from
// real signals already tracked elsewhere) — only the qualitative
// strengths/gaps/next-steps are AI-generated, and they're grounded in the
// computed breakdown, not free to invent their own assessment of readiness.
// ═══════════════════════════════════════════════════════════════════════════
app.post('/api/business/:id/funding-readiness', authRequired, async (req, res) => {
  const language = req.body?.language === 'fr' ? 'fr' : 'en';
  try {
    const account = await resolveAccount(req.userId);
    const context = await getBusinessContext(req.params.id, account.id);
    if (!context) return res.status(404).json({ error: 'Business not found' });
    const contextSummary = summarizeBusinessContextForAI(context) || 'No detailed context is available for this business yet.';

    const hasBusinessPlan = context.entrepreneurSessions.some(s => s.has_business_plan);
    let hasVerifiedFinancials = false;
    if (hasBusinessPlan) {
      const latestPlanRow = await pool.query(
        `SELECT business_plan FROM entrepreneur_sessions WHERE business_id = $1 AND business_plan IS NOT NULL ORDER BY created_at DESC LIMIT 1`,
        [req.params.id]
      );
      hasVerifiedFinancials = !!latestPlanRow.rows[0]?.business_plan?.computed_financials;
    }

    // "Real" growth tracking means at least one objective has been checked
    // in on beyond its initial seed value — not just that a goal exists.
    const growthTrackingRow = await pool.query(
      `SELECT go.id FROM growth_objectives go
       JOIN growth_progress_history gph ON gph.objective_id = go.id
       WHERE go.business_id = $1
       GROUP BY go.id HAVING COUNT(gph.id) > 1 LIMIT 1`,
      [req.params.id]
    );
    const hasGrowthTracking = growthTrackingRow.rows.length > 0;

    const bizRow = await pool.query('SELECT intelligence_snapshot, market_context FROM businesses WHERE id = $1', [req.params.id]);
    const hasBusinessIntelligence = !!bizRow.rows[0]?.intelligence_snapshot;
    const hasMarketContext = !!bizRow.rows[0]?.market_context;

    const competitorCountRow = await pool.query('SELECT COUNT(*) FROM tracked_competitors WHERE business_id = $1', [req.params.id]);
    const trackedCompetitorCount = parseInt(competitorCountRow.rows[0].count, 10);

    const completeness = computeBusinessCompletenessScore(context);
    const { score, breakdown } = computeFundingReadinessScore({
      hasBusinessPlan, hasVerifiedFinancials, hasGrowthTracking, hasBusinessIntelligence,
      hasMarketContext, trackedCompetitorCount, profileCompletenessPct: completeness.score
    });

    const BREAKDOWN_KEY_DESCRIPTIONS = {
      has_business_plan: 'Has a generated business plan',
      has_verified_financials: 'Has verified (not just estimated) financial data',
      has_growth_tracking: 'Has tracked growth progress over time',
      has_business_intelligence: 'Has a Business Intelligence analysis',
      has_market_context: 'Has a Market Context analysis',
      has_tracked_competitor: 'Tracks at least one named competitor',
      profile_completeness: 'Business profile completeness'
    };
    const prompt = `You are a startup funding advisor. This business has a COMPUTED, deterministic funding readiness score of ${score}/100 based on real signals (not your own estimate) — do not restate or recalculate this score, only explain and build on it.

THE COMPUTED BREAKDOWN (what's actually in place vs. missing):
${breakdown.map(b => `- ${b.met ? '✓' : '✗'} ${BREAKDOWN_KEY_DESCRIPTIONS[b.key] || b.key} (${b.points}/${b.maxPoints} points)`).join('\n')}

THE BUSINESS:
${contextSummary}

YOUR TASK: Explain what this score actually means for this specific business, grounded in the breakdown above — not generic fundraising advice. Identify genuine strengths already in place, the specific gaps that would most concern an investor, and concrete next steps to close them.

Return ONLY valid JSON, no markdown, in exactly this structure:
{
  "readiness_summary": "one or two sentences on what this score means for this business specifically",
  "strengths": ["specific strength already in place, tied to the breakdown", "strength 2 (optional)"],
  "gaps": ["specific gap that would concern an investor, tied to what's missing in the breakdown", "gap 2"],
  "recommended_next_steps": ["specific, actionable step to close the biggest gap", "step 2", "step 3 (optional)"],
  "confidence_note": "one honest sentence on what this assessment assumes or where it's less certain"
}`;

    const raw = await callAI({ persona: prompt + frenchInstruction(language, { jsonMode: true }), messages: [{ role: 'user', content: 'Produce the assessment now, as JSON only.' }], complexity: 'complex', context: { feature: 'funding_readiness', userId: req.userId }, maxTokens: 2000 });

    let assessment;
    try {
      assessment = extractJSON(raw);
    } catch (e) {
      console.error('Funding readiness JSON parse failed. Length:', e.message, '| Response length:', raw.length, '| Last 300 chars:', raw.slice(-300));
      throw new Error('Could not generate a funding readiness assessment — please try again');
    }
    for (const field of ['strengths', 'gaps', 'recommended_next_steps']) {
      if (!Array.isArray(assessment[field])) {
        console.error(`Funding readiness field "${field}" was not an array:`, typeof assessment[field]);
        throw new Error('Could not generate a funding readiness assessment — please try again');
      }
    }

    const fundingReadiness = { score, breakdown, ...assessment };
    await pool.query(
      'UPDATE businesses SET funding_readiness = $1, funding_readiness_fr = NULL, funding_readiness_generated_at = NOW() WHERE id = $2',
      [JSON.stringify(fundingReadiness), req.params.id]
    );

    // Opportunity Radar: only a genuine crossing into a stronger band fires
    // — staying in the same band, or dropping to a weaker one, never does.
    // The band is still updated either way, so a later re-crossing back up
    // is correctly detected as new rather than suppressed.
    const bandRank = { weak: 0, developing: 1, strong: 2 };
    const newBand = score >= 70 ? 'strong' : score >= 40 ? 'developing' : 'weak';
    const lastBandRow = await pool.query('SELECT funding_readiness_last_band, name FROM businesses WHERE id = $1', [req.params.id]);
    const lastBand = lastBandRow.rows[0]?.funding_readiness_last_band;
    const isUpgrade = !lastBand || bandRank[newBand] > bandRank[lastBand];
    if (isUpgrade) {
      const bandLabel = language === 'fr'
        ? { weak: 'faible', developing: 'en développement', strong: 'solide' }[newBand]
        : newBand;
      const { title, message } = alertText('fundingMilestoneReached', language, lastBandRow.rows[0]?.name || 'this business', bandLabel);
      await createAlert(account.id, req.params.id, 'funding_milestone_reached', 'opportunity', title, message, { band: newBand, score });
    }
    await pool.query('UPDATE businesses SET funding_readiness_last_band = $1 WHERE id = $2', [newBand, req.params.id]);

    res.json({ fundingReadiness, generatedAt: new Date().toISOString() });
  } catch (err) {
    console.error('Funding readiness generation error:', err.message);
    res.status(500).json({ error: safeErrorMessage(err, 'Failed to generate funding readiness assessment. Please try again.') });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// PHASE 8 — BUSINESS PLAN + FUNDING (Step 3: Investor Materials)
// A structured pitch deck outline grounded in whatever real data already
// exists for this business (business plan, funding readiness, business
// intelligence) — the financial slide restates verified numbers rather
// than inventing new ones.
// ═══════════════════════════════════════════════════════════════════════════
app.post('/api/business/:id/pitch-deck', authRequired, async (req, res) => {
  const language = req.body?.language === 'fr' ? 'fr' : 'en';
  try {
    const account = await resolveAccount(req.userId);
    const context = await getBusinessContext(req.params.id, account.id);
    if (!context) return res.status(404).json({ error: 'Business not found' });
    const contextSummary = summarizeBusinessContextForAI(context) || 'No detailed context is available for this business yet.';

    const bizRow = await pool.query('SELECT intelligence_snapshot, funding_readiness FROM businesses WHERE id = $1', [req.params.id]);
    const intelligence = bizRow.rows[0]?.intelligence_snapshot;
    const fundingReadiness = bizRow.rows[0]?.funding_readiness;

    const latestPlanRow = await pool.query(
      `SELECT business_plan FROM entrepreneur_sessions WHERE business_id = $1 AND business_plan IS NOT NULL ORDER BY created_at DESC LIMIT 1`,
      [req.params.id]
    );
    const businessPlan = latestPlanRow.rows[0]?.business_plan;

    let additionalContext = '';
    if (businessPlan) {
      additionalContext += `\n\nEXISTING BUSINESS PLAN (ground the deck in this, especially the financial slide — do not invent different figures than what's here):\n${JSON.stringify(businessPlan)}`;
    }
    if (fundingReadiness) {
      additionalContext += `\n\nFUNDING READINESS ASSESSMENT (score ${fundingReadiness.score}/100): Strengths: ${(fundingReadiness.strengths || []).join('; ')}. Gaps: ${(fundingReadiness.gaps || []).join('; ')}.`;
    }
    if (intelligence?.strengths?.length || intelligence?.threats?.length) {
      additionalContext += `\n\nBUSINESS INTELLIGENCE: Strengths: ${(intelligence.strengths || []).join('; ')}. Threats: ${(intelligence.threats || []).join('; ')}.`;
    }

    const prompt = `You are an investor-pitch consultant. Produce a structured pitch deck outline for this business — specific to this business, not a generic template with placeholder text.

THE BUSINESS:
${contextSummary}${additionalContext}

YOUR TASK: Produce exactly 9 slides in this order: Title, Problem, Solution, Market Opportunity, Business Model, Traction, Competition, Financial Highlights, The Ask. Each slide needs 3-5 concrete, specific bullet points — not generic pitch-deck filler. The Financial Highlights slide must restate only numbers that are actually known from the business plan or context above; if no verified numbers exist, say so honestly in that slide's content rather than inventing figures.

Return ONLY valid JSON, no markdown, in exactly this structure:
{
  "slides": [
    { "slide_number": 1, "title": "Title Slide", "content": ["business name and one-line tagline", "founder name if known"] },
    { "slide_number": 2, "title": "Problem", "content": ["specific point 1", "specific point 2"] }
  ],
  "confidence_note": "one honest sentence on what this deck assumes or where the underlying data is thin"
}`;

    const raw = await callAI({ persona: prompt + frenchInstruction(language, { jsonMode: true }), messages: [{ role: 'user', content: 'Produce the pitch deck outline now, as JSON only.' }], complexity: 'complex', context: { feature: 'pitch_deck', userId: req.userId }, maxTokens: 3000 });

    let pitchDeck;
    try {
      pitchDeck = extractJSON(raw);
    } catch (e) {
      console.error('Pitch deck JSON parse failed. Length:', e.message, '| Response length:', raw.length, '| Last 300 chars:', raw.slice(-300));
      throw new Error('Could not generate a pitch deck outline — please try again');
    }
    if (!Array.isArray(pitchDeck.slides)) {
      console.error('Pitch deck "slides" was not an array:', typeof pitchDeck.slides);
      throw new Error('Could not generate a pitch deck outline — please try again');
    }
    for (const slide of pitchDeck.slides) {
      if (!slide.title || !Array.isArray(slide.content)) {
        console.error('Pitch deck slide missing required fields:', slide);
        throw new Error('Could not generate a pitch deck outline — please try again');
      }
    }

    await pool.query(
      'UPDATE businesses SET pitch_deck = $1, pitch_deck_fr = NULL, pitch_deck_generated_at = NOW() WHERE id = $2',
      [JSON.stringify(pitchDeck), req.params.id]
    );

    res.json({ pitchDeck, generatedAt: new Date().toISOString() });
  } catch (err) {
    console.error('Pitch deck generation error:', err.message);
    res.status(500).json({ error: safeErrorMessage(err, 'Failed to generate pitch deck outline. Please try again.') });
  }
});

function buildPitchDeckDOCX(pitchDeck, businessName) {
  const children = [];
  children.push(new Paragraph({ text: `${businessName || 'Pitch Deck'} — Investor Pitch Outline`, heading: HeadingLevel.TITLE }));
  children.push(new Paragraph({
    children: [new TextRun({ text: `Generated ${new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })} · Arreyon Consult by G-DESIGNS LTD`, italics: true, size: 18, color: '777777' })]
  }));
  children.push(new Paragraph({ text: '' }));
  if (pitchDeck.confidence_note) {
    children.push(new Paragraph({ children: [new TextRun({ text: pitchDeck.confidence_note, italics: true, size: 18, color: '888888' })], spacing: { after: 200 } }));
  }

  (pitchDeck.slides || []).forEach(slide => {
    children.push(new Paragraph({ text: `Slide ${slide.slide_number || ''}: ${slide.title}`, heading: HeadingLevel.HEADING_1 }));
    (slide.content || []).forEach(point => {
      children.push(new Paragraph({ text: point, bullet: { level: 0 } }));
    });
    children.push(new Paragraph({ text: '' }));
  });

  children.push(new Paragraph({
    children: [new TextRun({ text: 'Arreyon Consult by G-DESIGNS LTD · consult.gdesignsme.com · This outline was AI-generated and is a starting point for a real pitch deck, not a finished one.', size: 15, color: 'AAAAAA', italics: true })],
    alignment: AlignmentType.CENTER
  }));

  const doc = new DocxDocument({ sections: [{ children }] });
  return Packer.toBuffer(doc);
}

app.get('/api/business/:id/pitch-deck/download', authRequired, async (req, res) => {
  try {
    const account = await resolveAccount(req.userId);
    const biz = await pool.query('SELECT name, website, pitch_deck FROM businesses WHERE id = $1 AND user_id = $2', [req.params.id, account.id]);
    if (!biz.rows.length) return res.status(404).json({ error: 'Business not found' });
    const business = biz.rows[0];
    if (!business.pitch_deck) return res.status(404).json({ error: 'No pitch deck outline has been generated yet for this business.' });

    const buffer = await buildPitchDeckDOCX(business.pitch_deck, business.name || business.website);
    const filename = sanitizeFilename(business.name || business.website);
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}-pitch-deck.docx"`);
    res.send(buffer);
  } catch (err) {
    console.error('Pitch deck download error:', err.message);
    res.status(500).json({ error: 'Failed to generate the download. Please try again.' });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// PHASE 8 — BUSINESS PLAN + FUNDING (Step 4: Share)
// One share token per business. The public read endpoint deliberately
// selects ONLY the specific fields meant for sharing — the business's name,
// its plan, funding readiness, and pitch deck — never the full business
// row, which holds far more (leads, growth objectives, internal notes,
// financial facts) that has no business being exposed on an unauthenticated
// link, however that link was obtained.
// ═══════════════════════════════════════════════════════════════════════════
app.post('/api/business/:id/share', authRequired, async (req, res) => {
  try {
    const account = await resolveAccount(req.userId);
    const biz = await pool.query('SELECT id FROM businesses WHERE id = $1 AND user_id = $2', [req.params.id, account.id]);
    if (!biz.rows.length) return res.status(404).json({ error: 'Business not found' });

    const token = crypto.randomBytes(32).toString('hex');
    await pool.query('UPDATE businesses SET share_token = $1, share_created_at = NOW() WHERE id = $2', [token, req.params.id]);

    res.json({ success: true, shareUrl: `${BASE_URL}/shared-plan.html?token=${token}` });
  } catch (err) {
    console.error('Share creation error:', err.message);
    res.status(500).json({ error: 'Failed to create share link. Please try again.' });
  }
});

app.delete('/api/business/:id/share', authRequired, async (req, res) => {
  try {
    const account = await resolveAccount(req.userId);
    const result = await pool.query(
      'UPDATE businesses SET share_token = NULL, share_created_at = NULL WHERE id = $1 AND user_id = $2 RETURNING id',
      [req.params.id, account.id]
    );
    if (!result.rows.length) return res.status(404).json({ error: 'Business not found' });
    res.json({ success: true });
  } catch (err) {
    console.error('Share revocation error:', err.message);
    res.status(500).json({ error: 'Failed to revoke share link. Please try again.' });
  }
});

app.get('/api/share/:token', async (req, res) => {
  try {
    const bizRow = await pool.query(
      'SELECT id, name, website, industry, funding_readiness, pitch_deck, share_created_at FROM businesses WHERE share_token = $1',
      [req.params.token]
    );
    if (!bizRow.rows.length) return res.status(404).json({ error: 'This share link is invalid or has been revoked.' });
    const business = bizRow.rows[0];

    const latestPlanRow = await pool.query(
      `SELECT business_plan FROM entrepreneur_sessions WHERE business_id = $1 AND business_plan IS NOT NULL ORDER BY created_at DESC LIMIT 1`,
      [business.id]
    );

    res.json({
      businessName: business.name || business.website,
      industry: business.industry,
      businessPlan: latestPlanRow.rows[0]?.business_plan || null,
      fundingReadiness: business.funding_readiness || null,
      pitchDeck: business.pitch_deck || null,
      sharedSince: business.share_created_at
    });
  } catch (err) {
    console.error('Public share view error:', err.message);
    res.status(500).json({ error: 'Failed to load this shared plan. Please try again.' });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// PHASE 8 / INCREMENT 1 — WEBSITE INTELLIGENCE & CONTROL: connection + read-only
//
// A website connection belongs to a specific Business Workspace (business_id),
// not the Arreyon account as a whole — unlike Google/HubSpot/Zoho, which are
// account-wide OAuth connections. Ownership is checked the same way as every
// other business-scoped endpoint (tracked_competitors, leads): resolve the
// account, then confirm the business belongs to it.
// ═══════════════════════════════════════════════════════════════════════════

// Records an event to the audit log — read-only events (connected,
// intelligence generated) from this increment onward, not just future
// write actions, so the log has real, useful content from day one rather
// than sitting empty until execution features exist.
// Real, deliberate feature tag — lets the activity log be viewed and
// cleared per-feature (SEO proposals vs categories/tags vs broken
// links, etc.) rather than as one single, undifferentiated list.
// Defaults to 'general' so a call site that doesn't specify one yet
// still logs correctly rather than failing.
async function logWebsiteAudit(websiteConnectionId, actorType, actorId, actionType, description, details, feature = 'general') {
  await pool.query(
    `INSERT INTO website_audit_log (website_connection_id, actor_type, actor_id, action_type, description, details, feature)
     VALUES ($1, $2, $3, $4, $5, $6, $7)`,
    [websiteConnectionId, actorType, actorId, actionType, description, JSON.stringify(details || {}), feature]
  );
}

// Real, deliberate central mapping — several routes (approve, reject,
// execute, confirm, re-verify) are generic and serve every proposal
// type through the same code path, so this is the one place that
// decides which real feature a given action_type actually belongs to,
// rather than guessing separately at every call site.
function featureForActionType(actionType) {
  if (actionType === 'update_meta_title' || actionType === 'update_meta_description') return 'seo_proposals';
  if (actionType === 'assign_taxonomy' || actionType === 'create_category' || actionType === 'create_tag') return 'taxonomy';
  if (actionType === 'generate_featured_image') return 'featured_images';
  if (actionType === 'remove_broken_link' || actionType === 'update_link_url') return 'broken_links';
  if (WORDPRESS_CONTENT_TYPES.includes(actionType) || WORDPRESS_ALT_TYPES.includes(actionType)) return 'seo_proposals';
  if (WORDPRESS_INLINK_TYPES.includes(actionType)) return 'seo_proposals';
  return 'general';
}

// Connect (or reconnect) a WordPress site to a business. Credentials are
// verified against the real site BEFORE anything is stored — an invalid
// username/Application Password never gets encrypted and saved.
// ═══════════════════════════════════════════════════════════════════════════
// SEO REST Bridge mu-plugin — a downloadable product asset, not something
// specific to any one customer's WordPress site. Every Arreyon customer
// connecting their own WordPress site hits the same underlying limitation
// (SEO plugins ship their meta fields as REST-read-only by default), so
// this is served directly by the app itself rather than living only in a
// support conversation — no auth required, since the content is generic
// and non-sensitive, and it may reasonably be handed to a client's own
// developer rather than downloaded by the Arreyon account holder directly.
// The newest published version of each WordPress plugin. Change a number here when its file changes: every site running an older
// version then shows an "update available" notice (see plugin-versions below). The version in each file's header comes from here.
const ARREYON_CONNECT_PLUGIN_VERSION = '1.1.0';
const ARREYON_SEO_BRIDGE_PLUGIN_VERSION = '2.1.0';

const ARREYON_SEO_REST_BRIDGE_PLUGIN = `<?php
/**
 * Plugin Name: Arreyon SEO REST Bridge
 * Description: Registers your SEO plugin's meta title/description fields
 *              for REST API write access, and automatically refreshes
 *              whichever SEO plugin's own cache needs it after a write,
 *              so Arreyon Consult's SEO Agent can actually update these
 *              fields AND have the change show up on the live page.
 *              Supports Yoast SEO, Rank Math, and All in One SEO.
 * Version:     ${ARREYON_SEO_BRIDGE_PLUGIN_VERSION}
 * Author:      G-DESIGNS LTD / Arreyon Consult
 *
 * INSTALLATION
 * 1. Upload this file to wp-content/mu-plugins/ on your WordPress site
 *    (create that folder if it doesn't exist yet).
 * 2. That's it - files in mu-plugins activate automatically. There is
 *    nothing to enable in the Plugins screen, and it cannot be
 *    accidentally deactivated the way a normal plugin can.
 *
 * WHY THIS EXISTS
 * WordPress core REST API can update a page/post's main title, but SEO
 * plugins ship their own meta fields as READ-ONLY by design - a write to
 * them silently succeeds at the API level while never actually saving.
 * Yoast SEO and Rank Math both genuinely store their SEO title and
 * description in real WordPress post meta, so this plugin registers
 * those exact fields for REST access. But saving that meta directly
 * (rather than through the plugin's own editor) does not automatically
 * refresh what either plugin actually shows on the live page - Yoast
 * keeps a separate, cached "indexable" record, and Rank Math serves
 * derived meta from its own cache layer - so both are real, well
 * documented gaps this plugin also closes automatically. All in One SEO
 * is a genuinely different case: it does not use post meta for these
 * fields at all, storing them instead in its own database tables, so
 * registering meta fields for it would never have worked in the first
 * place - an AIOSEO site should be updated through AIOSEO's own,
 * dedicated REST API field instead (aioseo_meta_data), which this
 * plugin's detection endpoint below exists to make discoverable.
 *
 * SECURITY
 * Every field registered here requires the same edit_posts capability a
 * normal WordPress user needs to edit that content - the Application
 * Password Arreyon uses must belong to a user who already has that
 * capability (Editor role or above). This plugin does not lower any
 * permission; it only exposes fields that already exist to the same
 * permission check WordPress already enforces everywhere else.
 */

if (!defined('ABSPATH')) {
    exit; // Never execute this file directly, only as a loaded WordPress plugin.
}

function arreyon_register_seo_rest_fields() {
    // Only registered for post types that are actually shown in the REST
    // API (public, REST-enabled types) - matches what Arreyon itself reads
    // and writes (pages and posts), and avoids registering fields on
    // internal post types that were never meant to be exposed.
    $post_types = get_post_types(['public' => true, 'show_in_rest' => true]);

    // Real, deliberate scope - only Yoast SEO and Rank Math, since both
    // genuinely store these values in real post meta. All in One SEO is
    // deliberately NOT registered here: it stores SEO titles and
    // descriptions in its own database tables, not post meta, so
    // registering meta keys for it would create real, orphaned,
    // never-read data rather than actually updating anything AIOSEO
    // itself uses - a write that "succeeds" while genuinely changing
    // nothing on the live page, which is worse than no write at all.
    $seo_fields = [
        // Yoast SEO
        '_yoast_wpseo_title'          => 'sanitize_text_field',
        '_yoast_wpseo_metadesc'       => 'sanitize_text_field',
        '_yoast_wpseo_focuskw'        => 'sanitize_text_field',
        // Rank Math
        'rank_math_title'             => 'sanitize_text_field',
        'rank_math_description'       => 'sanitize_text_field',
        'rank_math_focus_keyword'     => 'sanitize_text_field',
    ];

    foreach ($post_types as $post_type) {
        foreach ($seo_fields as $meta_key => $sanitize_callback) {
            register_post_meta($post_type, $meta_key, [
                'show_in_rest'      => true,
                'single'            => true,
                'type'              => 'string',
                'sanitize_callback' => $sanitize_callback,
                // Read requires nothing extra (these fields are visible to
                // anyone who can already see the post); write requires the
                // same capability WordPress already uses to decide whether
                // someone can edit that specific post.
                'auth_callback'     => function ($allowed, $meta_key, $post_id) {
                    return current_user_can('edit_post', $post_id);
                },
            ]);
        }
    }

    // Real, deliberate real schema-markup field — genuinely different
    // storage need from the plain-text SEO fields above, since this
    // real value is JSON, not a sentence, and sanitize_text_field
    // would mangle real quotes/braces. This round-trips through
    // json_decode/wp_json_encode instead: a real, valid JSON payload
    // survives intact; anything malformed is silently cleared to an
    // empty string rather than stored as broken, half-sanitized JSON.
    register_post_meta('post', '_arreyon_faq_schema', [
        'show_in_rest'      => true,
        'single'            => true,
        'type'              => 'string',
        'sanitize_callback' => function ($value) {
            $decoded = json_decode($value, true);
            if (json_last_error() !== JSON_ERROR_NONE || !is_array($decoded)) return '';
            return wp_json_encode($decoded);
        },
        'auth_callback' => function ($allowed, $meta_key, $post_id) {
            return current_user_can('edit_post', $post_id);
        },
    ]);
}
// Runs after both WordPress core (priority 10) and every major SEO plugin
// have registered their own post types and meta boxes, so this never
// races a plugin that hasn't finished setting up its own fields yet.
add_action('init', 'arreyon_register_seo_rest_fields', 20);

// Real, deliberate site-wide setting, separate from the per-post FAQ
// schema above — Organization/LocalBusiness schema describes the real
// business itself, not any one page, so it belongs on every real page
// of the site, stored once, not duplicated per post.
add_action('rest_api_init', function () {
    register_setting('general', 'arreyon_organization_schema', [
        'show_in_rest'      => true,
        'type'              => 'string',
        'sanitize_callback' => function ($value) {
            $decoded = json_decode($value, true);
            if (json_last_error() !== JSON_ERROR_NONE || !is_array($decoded)) return '';
            return wp_json_encode($decoded);
        },
        'default' => '',
    ]);
});

// Real, deliberate single output point for both real schema types —
// the FAQ schema for whichever single post is genuinely being viewed,
// and the Organization schema on every real page, site-wide. Neither
// ever touches post_content itself, so neither is ever at risk of
// being stripped by unfiltered_html restrictions the way a real
// <script> tag saved inside the post body could be on some real,
// more locked-down WordPress installs (multisite especially).
add_action('wp_head', function () {
    if (is_singular('post')) {
        $faq_schema = get_post_meta(get_the_ID(), '_arreyon_faq_schema', true);
        if (!empty($faq_schema)) {
            echo '<script type="application/ld+json">' . $faq_schema . '</script>';
        }
    }
    $org_schema = get_option('arreyon_organization_schema', '');
    if (!empty($org_schema)) {
        echo '<script type="application/ld+json">' . $org_schema . '</script>';
    }
});

// ============================================================================
// AUTOMATIC CACHE REFRESH — the real, documented reason a raw meta write
// alone is not enough for either Yoast or Rank Math to actually show the
// change on a live page. Hooked on the general updated_postmeta and
// added_postmeta actions (not something specific to the REST API), so
// this applies equally whether the write came from a real, remote REST
// request (a direct-connection site) or a local update_post_meta() call
// from a site's own poll-mode plugin — one real fix in one real place,
// not duplicated logic in two different codebases that could quietly
// drift apart from each other over time.
// ============================================================================

function arreyon_maybe_refresh_seo_cache($meta_id, $post_id, $meta_key, $meta_value) {
    if ($meta_key === '_yoast_wpseo_title' || $meta_key === '_yoast_wpseo_metadesc') {
        arreyon_force_yoast_indexable_rebuild($post_id);
    }
    if ($meta_key === 'rank_math_title' || $meta_key === 'rank_math_description') {
        arreyon_force_rank_math_cache_clear();
    }
}
add_action('updated_postmeta', 'arreyon_maybe_refresh_seo_cache', 10, 4);
add_action('added_postmeta', 'arreyon_maybe_refresh_seo_cache', 10, 4);

// Real, deliberate, defensive rebuild — Yoast SEO (v14+) caches what it
// actually renders on the live page in its own, separate database table
// (the "indexables" table), built from post meta but not kept in sync
// automatically when that meta is updated from outside code, only when
// saved through Yoast's own editor hooks. This is a well-documented,
// real Yoast limitation (confirmed via their own GitHub issue tracker),
// not something specific to this plugin. Wrapped defensively since this
// uses Yoast's own internal class surface (not a stable, public API by
// their own admission) — if it is ever unavailable or fails on some
// Yoast version, this simply does nothing further, real meta data is
// still correctly saved either way.
function arreyon_force_yoast_indexable_rebuild($post_id) {
    if (!function_exists('YoastSEO')) return;
    try {
        $post_type = get_post_type($post_id);
        $indexable_type = ($post_type === 'page') ? 'page' : 'post';
        // Real, deliberate construction via chr(92) rather than a
        // literal backslash-containing namespace string, which has
        // been silently corrupted by an external tool in the past
        // for this exact codebase — this construction has nothing
        // for that process to strip in the first place.
        $sep = chr(92);
        $builder_class = 'Yoast' . $sep . 'WP' . $sep . 'SEO' . $sep . 'Builders' . $sep . 'Indexable_Builder';
        $builder = YoastSEO()->classes->get($builder_class);
        if ($builder) {
            $builder->build_for_id_and_type($post_id, $indexable_type);
        }
    } catch (Throwable $e) {
        error_log('Arreyon SEO REST Bridge: could not force a Yoast indexable rebuild (non-fatal, real meta data is still correct): ' . $e->getMessage());
    }
}

// Real, deliberate, defensive cache clear — Rank Math serves derived,
// rendered meta from its own cache layer, which is especially visible
// on hosts using a persistent object cache (Redis/Memcached): a raw
// postmeta write can stay hidden from the live page until that cache
// naturally expires. rank_math_clear_cache() is Rank Math's own, public,
// documented function for exactly this — checked with function_exists
// so a site not running Rank Math, or an unexpected Rank Math version
// without this function, never breaks anything, just skips this step.
function arreyon_force_rank_math_cache_clear() {
    if (function_exists('rank_math_clear_cache')) {
        try {
            rank_math_clear_cache();
        } catch (Throwable $e) {
            error_log('Arreyon SEO REST Bridge: could not clear Rank Math cache (non-fatal, real meta data is still correct): ' . $e->getMessage());
        }
    }
}

// ============================================================================
// DETECTION ENDPOINT — lets Arreyon (both the remote server, for a real
// direct connection, and a site's own poll-mode plugin) ask a real
// question - "which SEO plugin does this real site actually run?" -
// rather than guessing from indirect signals or writing blindly to
// every supported plugin's fields at once and hoping one sticks. This
// is what makes it possible to route a write to the one, correct
// mechanism for whichever plugin is genuinely active, including AIOSEO,
// which needs an entirely different write path (its own REST field,
// not post meta) rather than a shared one.
// ============================================================================

function arreyon_detect_active_seo_plugin() {
    if (function_exists('YoastSEO') || defined('WPSEO_VERSION')) {
        return 'yoast';
    }
    if (function_exists('rank_math') || defined('RANK_MATH_VERSION')) {
        return 'rankmath';
    }
    if (function_exists('aioseo') || defined('AIOSEO_VERSION')) {
        return 'aioseo';
    }
    return null;
}

add_action('rest_api_init', function () {
    register_rest_route('arreyon-seo-bridge/v1', '/detected-plugin', [
        'methods'             => 'GET',
        'callback'            => function () {
            return ['plugin' => arreyon_detect_active_seo_plugin()];
        },
        // Real, deliberate low bar — this only reveals which SEO
        // plugin is active, not any real site content or credentials,
        // so it only requires being a genuinely real, authenticated
        // request, not a specific capability.
        'permission_callback' => function () {
            return is_user_logged_in();
        },
    ]);
});

// ── UPDATE NOTICE ──────────────────────────────────────────────────────────
// When a newer version of this plugin is published, a notice appears at the top of the Plugins screen with a button to
// download it. Nothing is installed automatically. The only thing asked of Arreyon is a short public page listing the
// newest version numbers — no account, login or site information is sent — remembered for 12 hours (1 hour if Arreyon
// could not be reached).
define('ARREYON_BRIDGE_VERSION', '${ARREYON_SEO_BRIDGE_PLUGIN_VERSION}');
define('ARREYON_BRIDGE_API_BASE', 'https://consult.gdesignsme.com');
define('ARREYON_BRIDGE_VERSIONS_CACHE_KEY', 'arreyon_bridge_latest_version');

function arreyon_bridge_is_french() {
    return strpos((string) get_locale(), 'fr') === 0;
}

// True when this file sits in wp-content/mu-plugins/ (the usual way to install it).
function arreyon_bridge_is_mu_plugin() {
    return defined('WPMU_PLUGIN_DIR') && strpos(wp_normalize_path(__FILE__), wp_normalize_path(WPMU_PLUGIN_DIR)) === 0;
}

function arreyon_bridge_latest_version() {
    $cached = get_transient(ARREYON_BRIDGE_VERSIONS_CACHE_KEY);
    if (is_string($cached)) {
        return $cached === '' ? null : $cached;
    }
    $found = '';
    $response = wp_remote_get(ARREYON_BRIDGE_API_BASE . '/api/website-connector/plugin-versions', array('timeout' => 4));
    if (!is_wp_error($response) && (int) wp_remote_retrieve_response_code($response) === 200) {
        $data = json_decode(wp_remote_retrieve_body($response), true);
        $version = (is_array($data) && isset($data['seoBridge']['version'])) ? $data['seoBridge']['version'] : '';
        if (is_string($version) && preg_match('/^[0-9]+([.][0-9]+){0,3}$/', $version)) {
            $found = $version;
        }
    }
    set_transient(ARREYON_BRIDGE_VERSIONS_CACHE_KEY, $found, $found !== '' ? 12 * HOUR_IN_SECONDS : HOUR_IN_SECONDS);
    return $found === '' ? null : $found;
}

function arreyon_bridge_new_version() {
    $latest = arreyon_bridge_latest_version();
    return ($latest !== null && version_compare($latest, ARREYON_BRIDGE_VERSION, '>')) ? $latest : null;
}

function arreyon_bridge_download_url() {
    return ARREYON_BRIDGE_API_BASE . (arreyon_bridge_is_mu_plugin() ? '/api/website-tools/seo-rest-bridge-plugin' : '/api/website-tools/seo-rest-bridge-plugin.zip');
}

function arreyon_bridge_update_text($new) {
    $mu = arreyon_bridge_is_mu_plugin();
    if (arreyon_bridge_is_french()) {
        $how = $mu ? 'Téléchargez-la et remplacez le fichier arreyon-seo-rest-bridge.php dans le dossier wp-content/mu-plugins/ de votre site par le nouveau.' : 'Téléchargez-la, puis allez dans Extensions → Ajouter → Téléverser une extension, choisissez le fichier et cliquez sur « Installer maintenant » ; WordPress proposera de remplacer la version actuelle.';
        return sprintf('Une nouvelle version d’Arreyon SEO REST Bridge est disponible : la version %1$s (vous utilisez la version %2$s). %3$s', $new, ARREYON_BRIDGE_VERSION, $how);
    }
    $how = $mu ? 'Download it and replace the file arreyon-seo-rest-bridge.php in your site’s wp-content/mu-plugins/ folder with the new one.' : 'Download it, then go to Plugins → Add New → Upload Plugin, choose the file and click “Install Now”; WordPress will offer to replace the current version.';
    return sprintf('A new version of Arreyon SEO REST Bridge is available: version %1$s (you are using version %2$s). %3$s', $new, ARREYON_BRIDGE_VERSION, $how);
}

add_action('admin_notices', function () {
    if (!current_user_can('manage_options')) {
        return;
    }
    $screen = function_exists('get_current_screen') ? get_current_screen() : null;
    if (!$screen || $screen->id !== 'plugins') {
        return;
    }
    $new = arreyon_bridge_new_version();
    if ($new === null) {
        return;
    }
    echo '<div class="notice notice-warning"><p>' . esc_html(arreyon_bridge_update_text($new)) . ' <a class="button button-primary" href="' . esc_url(arreyon_bridge_download_url()) . '">' . esc_html(arreyon_bridge_is_french() ? 'Télécharger la version ' . $new : 'Download version ' . $new) . '</a></p></div>';
});
`;

// Standalone CRC32 and a minimal single-file ZIP builder — no new npm
// dependency, since that would require the person deploying this to run
// npm install on their own server, a risk this file can't verify from
// here. Doesn't rely on Node's built-in zlib.crc32 either, since that was
// only added in Node 22.2.0 and this needs to work on whatever Node
// version the deployed server actually runs, not just this one.
function arreyonMakeCrcTable() {
  const table = [];
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    table[n] = c;
  }
  return table;
}
const ARREYON_CRC_TABLE = arreyonMakeCrcTable();
function arreyonCrc32(buf) {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) crc = ARREYON_CRC_TABLE[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
  return (crc ^ 0xFFFFFFFF) >>> 0;
}
// Builds a minimal, valid ZIP archive with one STORED (uncompressed) entry.
// entryPath must include the plugin's own folder (e.g.
// "arreyon-seo-rest-bridge/arreyon-seo-rest-bridge.php") since WordPress
// expects the plugin file to sit inside a folder matching its slug, not
// at the zip root.
function arreyonBuildSingleFileZip(entryPath, content) {
  const nameBuf = Buffer.from(entryPath, 'utf8');
  const dataBuf = Buffer.isBuffer(content) ? content : Buffer.from(content, 'utf8');
  const crc = arreyonCrc32(dataBuf);
  const dosTime = 0x0000, dosDate = 0x0021; // fixed, valid placeholder — the exact timestamp has no functional importance here

  const localHeader = Buffer.alloc(30);
  localHeader.writeUInt32LE(0x04034b50, 0);
  localHeader.writeUInt16LE(20, 4);
  localHeader.writeUInt16LE(0, 6);
  localHeader.writeUInt16LE(0, 8);
  localHeader.writeUInt16LE(dosTime, 10);
  localHeader.writeUInt16LE(dosDate, 12);
  localHeader.writeUInt32LE(crc, 14);
  localHeader.writeUInt32LE(dataBuf.length, 18);
  localHeader.writeUInt32LE(dataBuf.length, 22);
  localHeader.writeUInt16LE(nameBuf.length, 26);
  localHeader.writeUInt16LE(0, 28);
  const localEntry = Buffer.concat([localHeader, nameBuf, dataBuf]);

  const centralHeader = Buffer.alloc(46);
  centralHeader.writeUInt32LE(0x02014b50, 0);
  centralHeader.writeUInt16LE(20, 4);
  centralHeader.writeUInt16LE(20, 6);
  centralHeader.writeUInt16LE(0, 8);
  centralHeader.writeUInt16LE(0, 10);
  centralHeader.writeUInt16LE(dosTime, 12);
  centralHeader.writeUInt16LE(dosDate, 14);
  centralHeader.writeUInt32LE(crc, 16);
  centralHeader.writeUInt32LE(dataBuf.length, 20);
  centralHeader.writeUInt32LE(dataBuf.length, 24);
  centralHeader.writeUInt16LE(nameBuf.length, 28);
  centralHeader.writeUInt16LE(0, 30);
  centralHeader.writeUInt16LE(0, 32);
  centralHeader.writeUInt16LE(0, 34);
  centralHeader.writeUInt16LE(0, 36);
  centralHeader.writeUInt32LE(0, 38);
  centralHeader.writeUInt32LE(0, 42); // offset of local header — 0, since this is the only entry
  const centralEntry = Buffer.concat([centralHeader, nameBuf]);

  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(1, 8);
  eocd.writeUInt16LE(1, 10);
  eocd.writeUInt32LE(centralEntry.length, 12);
  eocd.writeUInt32LE(localEntry.length, 16);
  eocd.writeUInt16LE(0, 20);

  return Buffer.concat([localEntry, centralEntry, eocd]);
}

// The primary, recommended path: a proper .zip a person installs through
// WordPress's own familiar "Plugins → Add New → Upload Plugin" screen —
// no FTP, no cPanel file manager, no knowledge of what mu-plugins even
// are. Built fresh on each request (the file is tiny, so there's no
// reason to cache it) rather than requiring a zip to be committed and
// kept in sync with the source separately.
app.get('/api/website-tools/seo-rest-bridge-plugin.zip', (req, res) => {
  const zipBuf = arreyonBuildSingleFileZip('arreyon-seo-rest-bridge/arreyon-seo-rest-bridge.php', ARREYON_SEO_REST_BRIDGE_PLUGIN);
  res.setHeader('Content-Type', 'application/zip');
  res.setHeader('Content-Disposition', 'attachment; filename="arreyon-seo-rest-bridge.zip"');
  res.send(zipBuf);
});

// The raw .php file — kept for developers who specifically want the
// mu-plugin (auto-activates, can't be accidentally disabled) and already
// know how to reach their site's file system.
app.get('/api/website-tools/seo-rest-bridge-plugin', (req, res) => {
  res.setHeader('Content-Type', 'application/octet-stream');
  res.setHeader('Content-Disposition', 'attachment; filename="arreyon-seo-rest-bridge.php"');
  res.send(ARREYON_SEO_REST_BRIDGE_PLUGIN);
});

// ═══════════════════════════════════════════════════════════════════════════
// Arreyon Connect plugin — the code-based, non-technical-friendly connection
// path (Option 2). Reuses the same zip-builder helper as the SEO REST
// Bridge plugin above rather than duplicating that logic.
// ═══════════════════════════════════════════════════════════════════════════
const ARREYON_CONNECT_PLUGIN = `<?php
/**
 * Plugin Name: Arreyon Connect
 * Description: Connects this WordPress site to your Arreyon Consult account using a
 *              short connection code — no need to manually find or paste an
 *              Application Password. Generates its own Application Password
 *              internally and sends it to Arreyon on your behalf, once you enter
 *              the code shown in your Arreyon account.
 * Version:     ${ARREYON_CONNECT_PLUGIN_VERSION}
 * Author:      G-DESIGNS LTD / Arreyon Consult
 * Requires PHP: 7.4
 *
 * INSTALLATION
 * WordPress admin → Plugins → Add New → Upload Plugin → choose this file's
 * .zip → Install Now → Activate. Then go to Settings → Arreyon Connect.
 *
 * WHAT THIS PLUGIN DOES AND DOES NOT DO
 * It creates one Application Password for whichever WordPress user runs the
 * connection (must be able to manage_options — typically an Administrator),
 * and sends that password to Arreyon Consult over HTTPS. It does not read,
 * modify, or publish anything on this site by itself — all of that happens
 * later, through Arreyon's own approval workflow, using the credential this
 * plugin generated.
 */

if (!defined('ABSPATH')) {
    exit;
}

define('ARREYON_CONNECT_API_BASE', 'https://consult.gdesignsme.com');
define('ARREYON_CONNECT_OPTION_KEY', 'arreyon_connect_status');
define('ARREYON_POLLING_TOKEN_OPTION_KEY', 'arreyon_polling_token');
define('ARREYON_CRON_HOOK', 'arreyon_poll_for_actions');

// Real, deliberate custom interval — WordPress's built-in schedules
// (hourly, twicedaily, daily) are all far coarser than the few
// minutes of delay this is meant to keep an approved change within.
add_filter('cron_schedules', function ($schedules) {
    $schedules['arreyon_five_minutes'] = [
        'interval' => 300,
        'display'  => __('Every 5 Minutes (Arreyon Connect)'),
    ];
    return $schedules;
});

add_action('admin_menu', function () {
    add_menu_page(
        'Arreyon Connect',
        'Arreyon Connect',
        'manage_options',
        'arreyon-connect',
        'arreyon_connect_render_page',
        'dashicons-admin-links',
        80
    );
});

// The standard WordPress convention for plugin discoverability — a
// "Settings" link right on the plugin's own row (next to
// Deactivate/Delete) on the Plugins page, so a person doesn't have to
// already know this menu item exists somewhere in the sidebar to find it.
add_filter('plugin_action_links_' . plugin_basename(__FILE__), function ($actions) {
    $settings_link = '<a href="' . esc_url(admin_url('admin.php?page=arreyon-connect')) . '">' . esc_html__('Settings') . '</a>';
    array_unshift($actions, $settings_link);
    return $actions;
});

function arreyon_connect_render_page() {
    if (!current_user_can('manage_options')) {
        wp_die(esc_html__('You do not have permission to access this page.'));
    }

    $status = get_option(ARREYON_CONNECT_OPTION_KEY, null);
    $error = isset($_GET['arreyon_error']) ? sanitize_text_field(wp_unslash($_GET['arreyon_error'])) : null;
    ?>
    <div class="wrap">
        <h1>Arreyon Connect</h1>

        <?php arreyon_connect_render_update_notice(); ?>

        <?php if ($error): ?>
            <div class="notice notice-error"><p><?php echo esc_html($error); ?></p></div>
        <?php endif; ?>

        <?php if ($status && !empty($status['connected'])): ?>
            <div class="notice notice-success">
                <p>
                    🎉 <strong><?php echo esc_html($status['business_name'] ?: 'Your business'); ?></strong> is connected.<br>
                    Website: <?php echo esc_html(wp_parse_url(home_url(), PHP_URL_HOST)); ?><br>
                    Status: Connected<br>
                    WordPress: Detected<br>
                    Access: Read &amp; Analyze
                </p>
            </div>
            <p>To connect a different Arreyon account or business, enter a new connection code below.</p>
        <?php else: ?>
            <p>Install this plugin, then enter the connection code shown in your Arreyon Consult account to link this website — no need to find or copy any password yourself.</p>
        <?php endif; ?>

        <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>">
            <?php wp_nonce_field('arreyon_connect_action', 'arreyon_connect_nonce'); ?>
            <input type="hidden" name="action" value="arreyon_connect">
            <table class="form-table">
                <tr>
                    <th scope="row"><label for="arreyon_code">Connection Code</label></th>
                    <td>
                        <input type="text" id="arreyon_code" name="arreyon_code" class="regular-text" placeholder="ARREYON-XXXX-XXXX" required>
                        <p class="description">Shown in Arreyon Consult under Website → Connect Website.</p>
                    </td>
                </tr>
            </table>
            <?php submit_button('Connect to Arreyon'); ?>
        </form>
    </div>
    <?php
}

add_action('admin_post_arreyon_connect', function () {
    if (!current_user_can('manage_options')) {
        wp_die(esc_html__('You do not have permission to do this.'));
    }
    check_admin_referer('arreyon_connect_action', 'arreyon_connect_nonce');

    $redirect_base = admin_url('admin.php?page=arreyon-connect');
    $code = isset($_POST['arreyon_code']) ? sanitize_text_field(wp_unslash($_POST['arreyon_code'])) : '';

    if (empty($code)) {
        wp_safe_redirect(add_query_arg('arreyon_error', rawurlencode('Please enter a connection code.'), $redirect_base));
        exit;
    }

    // Application Passwords require HTTPS by default — checked before
    // attempting to create one, so the person gets a clear, specific
    // reason rather than a generic failure if this site doesn't qualify.
    if (!wp_is_application_passwords_available()) {
        wp_safe_redirect(add_query_arg('arreyon_error', rawurlencode('Application Passwords are not available on this site — WordPress requires HTTPS for this feature.'), $redirect_base));
        exit;
    }

    $user_id = get_current_user_id();
    $current_user = wp_get_current_user();

    // Include a timestamp in the name so reconnecting later (e.g. after a
    // previous attempt failed partway through) never collides with an
    // existing password of the same name, which WordPress rejects.
    $password_name = 'Arreyon Consult - ' . current_time('Y-m-d H:i:s');
    $created = WP_Application_Passwords::create_new_application_password($user_id, ['name' => $password_name]);

    if (is_wp_error($created)) {
        wp_safe_redirect(add_query_arg('arreyon_error', rawurlencode('Could not create an Application Password: ' . $created->get_error_message()), $redirect_base));
        exit;
    }

    list($new_password, $new_item) = $created;

    $response = wp_remote_post(ARREYON_CONNECT_API_BASE . '/api/website-connector/register', [
        'timeout' => 20,
        'headers' => ['Content-Type' => 'application/json'],
        'body' => wp_json_encode([
            'code' => $code,
            'siteUrl' => home_url(),
            'username' => $current_user->user_login,
            'appPassword' => $new_password,
        ]),
    ]);

    if (is_wp_error($response)) {
        // The handshake never reached Arreyon — the password this plugin
        // just created is orphaned and useless, so it's removed rather
        // than left behind silently.
        WP_Application_Passwords::delete_application_password($user_id, $new_item['uuid']);
        wp_safe_redirect(add_query_arg('arreyon_error', rawurlencode('Could not reach Arreyon Consult: ' . $response->get_error_message()), $redirect_base));
        exit;
    }

    $status_code = wp_remote_retrieve_response_code($response);
    $body = json_decode(wp_remote_retrieve_body($response), true);

    if ($status_code !== 200 || empty($body['success'])) {
        // Same reasoning — Arreyon rejected the handshake (an invalid or
        // expired code, for instance), so this side's freshly-created
        // password is cleaned up rather than left as a dangling,
        // never-used credential.
        WP_Application_Passwords::delete_application_password($user_id, $new_item['uuid']);
        $error_message = !empty($body['error']) ? $body['error'] : 'Arreyon Consult rejected the connection attempt.';
        wp_safe_redirect(add_query_arg('arreyon_error', rawurlencode($error_message), $redirect_base));
        exit;
    }

    update_option(ARREYON_CONNECT_OPTION_KEY, [
        'connected' => true,
        'business_name' => !empty($body['businessName']) ? sanitize_text_field($body['businessName']) : null,
        'connected_at' => current_time('mysql'),
    ]);

    // Real, deliberate fallback path — only present when Arreyon's own
    // verification request was blocked before it ever reached
    // WordPress (Cloudflare Bot Fight Mode being the known case this
    // exists for). This site's own outbound requests to Arreyon are
    // never subject to that same protection, so polling from this
    // side is what makes execution possible at all in that situation.
    if (!empty($body['connectionMode']) && $body['connectionMode'] === 'poll' && !empty($body['pollingToken'])) {
        update_option(ARREYON_POLLING_TOKEN_OPTION_KEY, sanitize_text_field($body['pollingToken']));
        if (!wp_next_scheduled(ARREYON_CRON_HOOK)) {
            wp_schedule_event(time(), 'arreyon_five_minutes', ARREYON_CRON_HOOK);
        }
    } else {
        // A normal, direct (push-mode) connection needs no polling at
        // all — clear any previous poll-mode leftovers from an
        // earlier connection attempt so this site doesn't keep
        // polling Arreyon for no reason.
        delete_option(ARREYON_POLLING_TOKEN_OPTION_KEY);
        $scheduled = wp_next_scheduled(ARREYON_CRON_HOOK);
        if ($scheduled) {
            wp_unschedule_event($scheduled, ARREYON_CRON_HOOK);
        }
    }

    wp_safe_redirect(add_query_arg('arreyon_connected', '1', $redirect_base));
    exit;
});

// ═══════════════════════════════════════════════════════════════════════════
// POLL-MODE EXECUTION — only ever runs when this site was connected in
// poll mode (a stored token exists), which only happens when Arreyon's
// own direct verification request was blocked before reaching WordPress
// at all (the known case: Cloudflare Bot Fight Mode on the free tier,
// which cannot be exempted by any rule). Runs the OPPOSITE direction
// from a normal push-mode connection: this site calls OUT to Arreyon —
// an outbound request Cloudflare's inbound bot protection never
// inspects — fetches whatever real, approved changes are waiting, and
// executes them locally using WordPress's own native functions rather
// than the REST API, then reports the real, immediate result back.
add_action(ARREYON_CRON_HOOK, 'arreyon_poll_and_execute_actions');

function arreyon_poll_and_execute_actions() {
    $token = get_option(ARREYON_POLLING_TOKEN_OPTION_KEY, null);
    if (empty($token)) {
        // Not (or no longer) in poll mode — nothing to do. This can
        // happen if the cron event fires once more right after a
        // reconnect switched this site back to push mode.
        return;
    }

    $response = wp_remote_get(
        ARREYON_CONNECT_API_BASE . '/api/website-connector/poll?token=' . rawurlencode($token),
        ['timeout' => 15]
    );

    if (is_wp_error($response)) {
        error_log('Arreyon Connect: could not reach Arreyon to poll for actions: ' . $response->get_error_message());
        return;
    }
    if (wp_remote_retrieve_response_code($response) !== 200) {
        error_log('Arreyon Connect: polling request rejected (status ' . wp_remote_retrieve_response_code($response) . ')');
        return;
    }

    $body = json_decode(wp_remote_retrieve_body($response), true);
    $actions = !empty($body['actions']) && is_array($body['actions']) ? $body['actions'] : [];

    foreach ($actions as $action) {
        arreyon_execute_one_action($token, $action);
    }

    if (!empty($body['contentRequested'])) {
        arreyon_gather_and_report_content($token);
    }
}

// Real, deliberate local gathering — reads real, live page/post data
// straight from WordPress's own database, the same real data a direct
// REST read would return, but without ever making an inbound request
// to this site from Arreyon (the exact thing blocked in poll mode).
// Mirrors fetchWordPressContent's real shape on the Arreyon side, so
// this reported data slots into the exact same downstream analysis
// with no special-casing needed there.
function arreyon_gather_and_report_content($token) {
    $seo_plugin = arreyon_connect_detect_seo_plugin();
    $pages = arreyon_gather_content_for_type('page', $seo_plugin);
    $posts = arreyon_gather_content_for_type('post', $seo_plugin);

    $counts_pages = wp_count_posts('page');
    $counts_posts = wp_count_posts('post');

    arreyon_report_content($token, [
        'pages' => $pages,
        'posts' => $posts,
        'totalPageCount' => isset($counts_pages->publish) ? (int) $counts_pages->publish : count($pages),
        'totalPostCount' => isset($counts_posts->publish) ? (int) $counts_posts->publish : count($posts),
        'categories' => arreyon_gather_taxonomy('category'),
        'tags' => arreyon_gather_taxonomy('post_tag'),
        'media' => arreyon_gather_media(),
    ]);
}

// Real, deliberate small, bounded read — mirrors fetchWordPressContent's
// own real per_page=30 cap on the direct-connection side.
function arreyon_gather_media() {
    $items = get_posts(['post_type' => 'attachment', 'post_status' => 'inherit', 'post_mime_type' => 'image', 'numberposts' => 30, 'orderby' => 'date', 'order' => 'DESC']);
    $results = [];
    foreach ($items as $item) {
        $metadata = wp_get_attachment_metadata($item->ID);
        $results[] = [
            'id' => $item->ID,
            'title' => html_entity_decode(get_the_title($item), ENT_QUOTES, 'UTF-8'),
            'url' => wp_get_attachment_url($item->ID),
            'altText' => get_post_meta($item->ID, '_wp_attachment_image_alt', true) ?: '',
            'width' => isset($metadata['width']) ? (int) $metadata['width'] : null,
            'height' => isset($metadata['height']) ? (int) $metadata['height'] : null,
            'mimeType' => $item->post_mime_type,
        ];
    }
    return $results;
}

// Real, deliberate small, bounded read — mirrors fetchWordPressContent's
// own real per_page=100 cap on the direct-connection side, since a
// real site's full taxonomy list is genuinely useful to see in its
// entirety when choosing one for a new post, not just a sample.
// Real, deliberate case-insensitive lookup before ever creating —
// "SEO" and "seo" should resolve to the exact same real term, not
// create a genuine duplicate that only differs by letter case.
function arreyon_find_or_create_term($name, $taxonomy) {
    if ($name === '') return null;
    $existing = get_term_by('name', $name, $taxonomy);
    if ($existing) return $existing->term_id;
    $result = wp_insert_term($name, $taxonomy);
    if (is_wp_error($result)) {
        $error_data = $result->get_error_data();
        if (is_array($error_data) && isset($error_data['term_id'])) return $error_data['term_id'];
        return null;
    }
    return $result['term_id'];
}

function arreyon_gather_taxonomy($taxonomy) {
    $terms = get_terms(['taxonomy' => $taxonomy, 'hide_empty' => false, 'number' => 100]);
    if (is_wp_error($terms) || !is_array($terms)) return [];
    $results = [];
    foreach ($terms as $term) {
        $results[] = ['id' => $term->term_id, 'name' => html_entity_decode($term->name, ENT_QUOTES, 'UTF-8'), 'count' => (int) $term->count];
    }
    return $results;
}

function arreyon_gather_content_for_type($post_type, $seo_plugin) {
    // Real, deliberate cap — matches fetchWordPressContent's own
    // per_page=20 real limit on the direct-connection side, since the
    // AI analysis step downstream only ever looks at a real, bounded
    // sample either way.
    $items = get_posts(['post_type' => $post_type, 'post_status' => 'publish', 'numberposts' => 20, 'orderby' => 'date', 'order' => 'DESC']);
    $results = [];
    foreach ($items as $item) {
        $raw_content = $item->post_content;
        $body_text = wp_strip_all_tags($raw_content);
        $word_count = $body_text ? str_word_count($body_text) : 0;
        $heading_count = substr_count($raw_content, '<h1') + substr_count($raw_content, '<h2') + substr_count($raw_content, '<h3');
        $entry = [
            'id' => $item->ID,
            'title' => html_entity_decode(get_the_title($item), ENT_QUOTES, 'UTF-8'),
            'slug' => $item->post_name,
            'url' => get_permalink($item),
            'wordCount' => $word_count,
            'headings' => $heading_count,
            'metaDescription' => arreyon_get_local_meta_description($item->ID, $seo_plugin),
            'metaTitle' => arreyon_get_local_meta_title($item->ID, $seo_plugin),
            'bodyExcerpt' => substr($body_text, 0, 500),
            'hasFeaturedImage' => has_post_thumbnail($item->ID),
        ];
        // Real, deliberate limit to posts only — pages don't support
        // categories or tags at all in standard WordPress, so this
        // mirrors the same real constraint fetchWordPressContent
        // applies on the direct-connection side.
        if ($post_type === 'post') {
            $entry['categoryIds'] = wp_get_post_categories($item->ID);
            $entry['tagIds'] = wp_get_post_tags($item->ID, ['fields' => 'ids']);
        }
        $results[] = $entry;
    }
    return $results;
}

// Real, deliberate plugin-aware read — mirrors the same real per-
// plugin distinction arreyon_execute_one_action already makes for
// writing: Yoast and Rank Math both genuinely store this in real post
// meta, but All in One SEO does not, storing it instead in its own
// real database table, so reading it needs a real, direct, read-only
// query against that table rather than a meta lookup that would
// always come back empty on an AIOSEO site.
function arreyon_get_local_meta_description($post_id, $seo_plugin) {
    if ($seo_plugin === 'yoast') {
        $value = get_post_meta($post_id, '_yoast_wpseo_metadesc', true);
        return $value !== '' ? $value : null;
    }
    if ($seo_plugin === 'rankmath') {
        $value = get_post_meta($post_id, 'rank_math_description', true);
        return $value !== '' ? $value : null;
    }
    if ($seo_plugin === 'aioseo') {
        global $wpdb;
        $table = $wpdb->prefix . 'aioseo_posts';
        $value = $wpdb->get_var($wpdb->prepare("SELECT description FROM {$table} WHERE post_id = %d", $post_id));
        return $value ? $value : null;
    }
    return null;
}

// Real, deliberate mirror of the function above, for the meta title
// instead of the description — same real, per-plugin distinction,
// since it's the same real storage mechanism either field uses.
function arreyon_get_local_meta_title($post_id, $seo_plugin) {
    if ($seo_plugin === 'yoast') {
        $value = get_post_meta($post_id, '_yoast_wpseo_title', true);
        return $value !== '' ? $value : null;
    }
    if ($seo_plugin === 'rankmath') {
        $value = get_post_meta($post_id, 'rank_math_title', true);
        return $value !== '' ? $value : null;
    }
    if ($seo_plugin === 'aioseo') {
        global $wpdb;
        $table = $wpdb->prefix . 'aioseo_posts';
        $value = $wpdb->get_var($wpdb->prepare("SELECT title FROM {$table} WHERE post_id = %d", $post_id));
        return $value ? $value : null;
    }
    return null;
}

function arreyon_report_content($token, $content) {
    $response = wp_remote_post(ARREYON_CONNECT_API_BASE . '/api/website-connector/report-content', [
        'timeout' => 20,
        'headers' => ['Content-Type' => 'application/json'],
        'body' => wp_json_encode(array_merge(['token' => $token], $content)),
    ]);

    if (is_wp_error($response)) {
        // Real, deliberate no-op beyond logging — the next scheduled
        // poll will naturally see contentRequested still set (Arreyon
        // never learned this succeeded) and try again on its own,
        // rather than this needing its own separate retry logic.
        error_log('Arreyon Connect: could not report content back to Arreyon: ' . $response->get_error_message());
    }
}


// Executes a single real, already-approved change locally, then
// immediately reads back what was actually saved — within the same
// PHP request, before any cache anywhere has a chance to interfere —
// and reports that real outcome back to Arreyon.
// Real, deliberate second verification layer — a raw database write
// succeeding is not proof the actual, live, rendered page reflects
// it yet (the exact same real distinction the direct-connection path
// already makes via Yoast's own rendered output). This checks the
// real, public page URL itself — the same thing a real visitor's
// browser would load — which works correctly regardless of which of
// the three supported SEO plugins is actually active, since all of
// them render a standard <title> and <meta name="description"> tag.
// Real, deliberate string-function approach — NOT regex. A prior
// version of this used preg_match with several backslash-escaped
// characters, and every one of them was silently stripped somewhere
// between delivery and what actually got installed, twice — a real,
// external problem, not something fixable from this side. Since
// nothing here forces a choice between regex and correctness, this
// rewrite avoids backslash-dependent syntax entirely, using plain,
// boring position-finding instead.
function arreyon_extract_tag_value($html, $start_marker, $end_marker) {
    $start_pos = stripos($html, $start_marker);
    if ($start_pos === false) return null;
    $start_pos += strlen($start_marker);
    $end_pos = stripos($html, $end_marker, $start_pos);
    if ($end_pos === false) return null;
    return substr($html, $start_pos, $end_pos - $start_pos);
}

function arreyon_extract_meta_description($html) {
    // Real, deliberate manual scan for a real <meta name="description"
    // ...> tag, handling both attribute orders (content before or
    // after name) and both quote styles, without regex at all.
    $name_pos = stripos($html, 'name="description"');
    if ($name_pos === false) $name_pos = stripos($html, "name='description'");
    if ($name_pos === false) return null;

    $tag_start = strrpos(substr($html, 0, $name_pos), '<meta');
    if ($tag_start === false) return null;
    $tag_end = strpos($html, '>', $name_pos);
    if ($tag_end === false) return null;
    $tag = substr($html, $tag_start, $tag_end - $tag_start + 1);

    $content_pos = stripos($tag, 'content="');
    $quote_char = '"';
    if ($content_pos === false) {
        $content_pos = stripos($tag, "content='");
        $quote_char = "'";
    }
    if ($content_pos === false) return null;

    $value_start = $content_pos + strlen('content=') + 1;
    $value_end = strpos($tag, $quote_char, $value_start);
    if ($value_end === false) return null;
    return substr($tag, $value_start, $value_end - $value_start);
}

function arreyon_verify_rendered_page_once($target_wp_id, $field, $expected_value) {
    $permalink = get_permalink($target_wp_id);
    if (!$permalink) {
        return ['matched' => false, 'error' => 'Could not determine the real, live URL for this page to verify it.'];
    }
    // Real, deliberate cache-busting query parameter — Hostinger (and
    // many other hosts) run LiteSpeed's own full-page cache (LSCache)
    // by default, which can keep serving a real, still-cached copy of
    // this exact page for a short window after a genuine write, with
    // no guarantee the postmeta update alone triggers an immediate
    // cache purge for it. A never-before-seen URL forces a real,
    // fresh render straight from WordPress rather than risking a
    // stale, cached response — a page cache has nothing cached under
    // a URL it has never seen.
    $bust_url = $permalink . (strpos($permalink, '?') !== false ? '&' : '?') . 'arreyon_verify=' . uniqid();
    $response = wp_remote_get($bust_url, ['timeout' => 15]);
    if (is_wp_error($response)) {
        return ['matched' => false, 'error' => 'Could not fetch the real, live page to verify it: ' . $response->get_error_message()];
    }
    $html = wp_remote_retrieve_body($response);
    $decoded_expected = html_entity_decode($expected_value, ENT_QUOTES, 'UTF-8');

    if ($field === 'title') {
        // Real, deliberate "contains" check, not exact equality — a
        // rendered <title> tag typically includes the site own
        // title template (e.g. "Page Title | Site Name"), so the
        // real, live title genuinely reflecting this change usually
        // means it appears WITHIN the full rendered tag, not that
        // the whole tag equals just this value alone.
        $rendered_title = arreyon_extract_tag_value($html, '<title>', '</title>');
        if ($rendered_title !== null) {
            $rendered_title = html_entity_decode(trim($rendered_title), ENT_QUOTES, 'UTF-8');
            $matched = (strpos($rendered_title, $decoded_expected) !== false);
            $error = $matched ? null : ('The real, live page title tag currently reads: "' . $rendered_title . '" and does not yet reflect this change.');
            return ['matched' => $matched, 'error' => $error];
        }
        return ['matched' => false, 'error' => 'Could not find a real title tag on the live page to verify against.'];
    }

    if ($field === 'description') {
        $rendered_description = arreyon_extract_meta_description($html);
        if ($rendered_description !== null) {
            $rendered_description = html_entity_decode($rendered_description, ENT_QUOTES, 'UTF-8');
            $matched = ($rendered_description === $decoded_expected);
            $error = $matched ? null : ('The real, live page meta description currently reads: "' . $rendered_description . '" and does not yet reflect this change. The underlying data is correct; this is most likely a caching layer (this site has an SEO plugin, a caching plugin, or Cloudflare itself) that has not caught up yet.');
            return ['matched' => $matched, 'error' => $error];
        }
        return ['matched' => false, 'error' => 'Could not find a real meta description tag on the live page to verify against.'];
    }

    return ['matched' => false, 'error' => 'Unrecognized field for rendered-page verification.'];
}

// Real, deliberate one-retry wrapper — even with the cache-busting
// URL above forcing a fresh render, WordPress's own object cache or
// a real, ordinary propagation delay on the host can still mean the
// very first check lands a moment too early. A single short pause
// and one retry catches this real, common timing case without
// turning a genuinely wrong value into a false "verified" — a
// second attempt that still doesn't match is treated as a real,
// final answer, not retried indefinitely.
function arreyon_verify_rendered_page($target_wp_id, $field, $expected_value) {
    $first = arreyon_verify_rendered_page_once($target_wp_id, $field, $expected_value);
    if ($first['matched']) {
        return $first;
    }
    sleep(2);
    return arreyon_verify_rendered_page_once($target_wp_id, $field, $expected_value);
}

function arreyon_execute_one_action($token, $action) {
    $action_id = isset($action['id']) ? $action['id'] : null;
    $action_type = isset($action['actionType']) ? $action['actionType'] : '';
    $target_wp_id = isset($action['targetWpId']) ? (int) $action['targetWpId'] : 0;
    $target_type = isset($action['targetType']) ? $action['targetType'] : 'post';
    $change = isset($action['change']) && is_array($action['change']) ? $action['change'] : [];

    if (!$action_id) {
        arreyon_report_action_result($token, $action_id, false, false, 'Received an incomplete action from Arreyon - missing id.');
        return;
    }

    // Real, deliberate early branch — the real image itself was
    // already generated server-side (Arreyon holds the real OpenAI
    // key, never this plugin), arriving here as real base64 bytes to
    // upload locally using WordPress's own, native media functions,
    // the exact same real path the WordPress admin UI itself uses.
    if ($action_type === 'generate_featured_image') {
        if (!$target_wp_id || empty($change['imageBase64'])) {
            arreyon_report_action_result($token, $action_id, false, false, 'Received an incomplete image action from Arreyon - missing target or image data.');
            return;
        }
        require_once ABSPATH . 'wp-admin/includes/image.php';
        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/media.php';

        $decoded = base64_decode($change['imageBase64']);
        if ($decoded === false) {
            arreyon_report_action_result($token, $action_id, false, false, 'Could not decode the real image data received from Arreyon.');
            return;
        }
        $title = !empty($change['imageTitle']) ? $change['imageTitle'] : 'Featured Image';
        $filename = sanitize_file_name(strtolower($title)) . '.png';

        $upload = wp_upload_bits($filename, null, $decoded);
        if (!empty($upload['error'])) {
            arreyon_report_action_result($token, $action_id, false, false, 'WordPress rejected saving the real image file: ' . $upload['error']);
            return;
        }

        $attachment_id = wp_insert_attachment([
            'post_mime_type' => 'image/png',
            'post_title' => $title,
            'post_status' => 'inherit',
        ], $upload['file'], $target_wp_id);
        if (is_wp_error($attachment_id) || !$attachment_id) {
            arreyon_report_action_result($token, $action_id, false, false, 'WordPress rejected creating the real media item.');
            return;
        }

        $attachment_data = wp_generate_attachment_metadata($attachment_id, $upload['file']);
        wp_update_attachment_metadata($attachment_id, $attachment_data);
        if (!empty($change['altText'])) {
            update_post_meta($attachment_id, '_wp_attachment_image_alt', $change['altText']);
        }

        set_post_thumbnail($target_wp_id, $attachment_id);

        // Real, deliberate immediate verification — reads the post's
        // real, saved thumbnail id back rather than trusting the set
        // call above succeeded just because it didn't throw.
        $saved_thumbnail_id = (int) get_post_thumbnail_id($target_wp_id);
        if ($saved_thumbnail_id === (int) $attachment_id) {
            arreyon_report_action_result($token, $action_id, true, true, null);
        } else {
            arreyon_report_action_result($token, $action_id, true, false, 'The image was uploaded, but the post real, saved featured image does not yet reflect it.');
        }
        return;
    }

    // Real, deliberate early branch — a category/tag creation has no
    // existing page or post to target at all (that's the whole real
    // difference from a title/description change), so it's handled
    // as its own, separate real case before the target_wp_id
    // requirement below, which only makes sense for an action that
    // genuinely does target an existing piece of content.
    if ($action_type === 'create_category' || $action_type === 'create_tag') {
        $taxonomy = ($action_type === 'create_tag') ? 'post_tag' : 'category';
        $name = isset($change['name']) ? trim($change['name']) : '';
        if ($name === '') {
            arreyon_report_action_result($token, $action_id, false, false, 'No name was provided to create.');
            return;
        }
        $result = wp_insert_term($name, $taxonomy);
        if (is_wp_error($result)) {
            $error_data = $result->get_error_data();
            if (is_array($error_data) && isset($error_data['term_id'])) {
                // Real, deliberate treatment as success — a genuine
                // duplicate means the real, intended term already
                // exists, which is the actual real-world outcome the
                // person wanted, not a failure to report as one.
                arreyon_report_action_result($token, $action_id, true, true, null);
                return;
            }
            arreyon_report_action_result($token, $action_id, false, false, 'WordPress rejected creating this: ' . $result->get_error_message());
            return;
        }
        arreyon_report_action_result($token, $action_id, true, true, null);
        return;
    }

    // Real, deliberate second early branch — assigning a category/tag
    // to a real, existing post is neither a title/description change
    // nor a brand-new, standalone term creation; it resolves each
    // suggested name into a real term id (reusing an existing match
    // case-insensitively, creating only if genuinely nothing matches)
    // and sets those ids directly on the post.
    if ($action_type === 'assign_taxonomy') {
        if (!$target_wp_id) {
            arreyon_report_action_result($token, $action_id, false, false, 'Received an incomplete action from Arreyon - missing target.');
            return;
        }
        $category_id = null;
        $tag_ids = [];
        if (!empty($change['category'])) {
            $category_id = arreyon_find_or_create_term(trim($change['category']), 'category');
        }
        if (!empty($change['tags']) && is_array($change['tags'])) {
            foreach ($change['tags'] as $tag_name) {
                $tag_id = arreyon_find_or_create_term(trim($tag_name), 'post_tag');
                if ($tag_id) $tag_ids[] = $tag_id;
            }
        }
        if (!$category_id && empty($tag_ids)) {
            arreyon_report_action_result($token, $action_id, false, false, 'Could not resolve the suggested category or tags to real WordPress terms.');
            return;
        }
        if ($category_id) wp_set_post_categories($target_wp_id, [$category_id]);
        if (!empty($tag_ids)) wp_set_post_tags($target_wp_id, $tag_ids);

        // Real, deliberate verification — read the post's real, saved
        // term assignments back rather than trusting the set calls
        // above succeeded just because they didn't throw.
        $saved_categories = wp_get_post_categories($target_wp_id);
        $saved_tags = wp_get_post_tags($target_wp_id, ['fields' => 'ids']);
        $category_ok = !$category_id || in_array($category_id, $saved_categories);
        $tags_ok = empty($tag_ids) || !array_diff($tag_ids, $saved_tags);
        if ($category_ok && $tags_ok) {
            arreyon_report_action_result($token, $action_id, true, true, null);
        } else {
            arreyon_report_action_result($token, $action_id, true, false, 'The update was applied, but the post real, saved categories/tags do not yet fully reflect it.');
        }
        return;
    }

    if (!$target_wp_id) {
        arreyon_report_action_result($token, $action_id, false, false, 'Received an incomplete action from Arreyon - missing target.');
        return;
    }

    // executed: the real write itself genuinely succeeded.
    // verified: the real, live, rendered page actually reflects it.
    // These are kept as two real, separate facts - exactly the same
    // distinction the direct-connection path already makes - rather
    // than collapsed into one, since a write succeeding is not proof
    // the change is actually visible yet.
    $executed = false;
    $verified = false;
    $error = null;

    // Real, deliberate detection - which of the three supported SEO
    // plugins does this real site genuinely run - rather than writing
    // to every plugin's fields at once and hoping one sticks. This
    // matters most for All in One SEO: unlike Yoast and Rank Math, it
    // does not store its SEO title/description in post meta at all,
    // so update_post_meta() would never have worked for it in the
    // first place, regardless of any cache-clearing after the fact.
    // Given a distinct name (not shared with the REST Bridge plugin's
    // own, separate copy of this same real check) since both plugins
    // are meant to be installed together on the same real site, and
    // PHP function names are global - two plugins defining the exact
    // same name would be a real, fatal "cannot redeclare" error the
    // moment both are active, not a hypothetical one.
    $seo_plugin = arreyon_connect_detect_seo_plugin();
    $field = !empty($change['metaTitle']) ? 'title' : (!empty($change['metaDescription']) ? 'description' : null);
    $new_value = ($field === 'title') ? $change['metaTitle'] : (($field === 'description') ? $change['metaDescription'] : null);

    if (!$field) {
        $error = 'This proposed change has no recognized field to execute.';
    } elseif ($seo_plugin === 'aioseo') {
        // Real, deliberate REST-based write - AIOSEO's own, dedicated
        // REST field (aioseo_meta_data), not post meta at all, since
        // that is genuinely how AIOSEO 4.9.8+ expects this to be
        // written. rest_do_request() runs this through the exact same
        // real WordPress REST machinery a genuine external request
        // would use, including AIOSEO's own handling of it, rather
        // than trying to reverse-engineer its internal database
        // tables directly.
        $route = ($target_type === 'page') ? '/wp/v2/pages/' . $target_wp_id : '/wp/v2/posts/' . $target_wp_id;
        $request = new WP_REST_Request('POST', $route);
        $request->set_body_params(['aioseo_meta_data' => [$field => $new_value]]);
        $response = rest_do_request($request);
        if ($response->is_error()) {
            $error = 'AIOSEO rejected the update: ' . $response->as_error()->get_error_message();
        } else {
            $executed = true;
            $field_type = ($field === 'title') ? 'title' : 'description';
            $rendered = arreyon_verify_rendered_page($target_wp_id, $field_type, $new_value);
            $verified = $rendered['matched'];
            if (!$verified) $error = $rendered['error'];
        }
    } elseif ($seo_plugin === 'yoast' || $seo_plugin === 'rankmath' || $seo_plugin === null) {
        // Real, deliberate fallback to "write both plugins' real
        // fields" when no specific plugin was detected - genuinely
        // harmless when neither is active (both writes simply sit
        // unused), and correct when detection itself could not tell
        // which of the two is really running. The REST Bridge
        // plugin's own hooks automatically refresh whichever of these
        // two real caches actually needs it once this write happens,
        // regardless of which plugin's field this specific write
        // targeted - no explicit rebuild call needed here at all.
        $yoast_key = ($field === 'title') ? '_yoast_wpseo_title' : '_yoast_wpseo_metadesc';
        $rankmath_key = ($field === 'title') ? 'rank_math_title' : 'rank_math_description';
        update_post_meta($target_wp_id, $yoast_key, $new_value);
        update_post_meta($target_wp_id, $rankmath_key, $new_value);
        // update_post_meta returns false both on genuine failure AND
        // when the new value is identical to the existing one - so
        // this reads the real, current values back rather than
        // trusting the return value alone to decide success.
        $matched = get_post_meta($target_wp_id, $yoast_key, true) === $new_value
            || get_post_meta($target_wp_id, $rankmath_key, true) === $new_value;
        if ($matched) {
            $executed = true;
            $rendered = arreyon_verify_rendered_page($target_wp_id, $field, $new_value);
            $verified = $rendered['matched'];
            if (!$verified) $error = $rendered['error'];
        } else {
            $error = 'The value was sent to WordPress, but the saved value does not match what was intended for either Yoast SEO or Rank Math.';
        }
    }

    arreyon_report_action_result($token, $action_id, $executed, $verified, $error);
}

// Real, deliberate, distinctly-named detection - deliberately not
// shared with the REST Bridge plugin's own, separate copy of this
// same real check, since both plugins are meant to be installed
// together on the same real site and PHP function names are global.
function arreyon_connect_detect_seo_plugin() {
    if (function_exists('YoastSEO') || defined('WPSEO_VERSION')) return 'yoast';
    if (function_exists('rank_math') || defined('RANK_MATH_VERSION')) return 'rankmath';
    if (function_exists('aioseo') || defined('AIOSEO_VERSION')) return 'aioseo';
    return null;
}


function arreyon_report_action_result($token, $action_id, $executed, $verified, $error) {
    $response = wp_remote_post(ARREYON_CONNECT_API_BASE . '/api/website-connector/report-result', [
        'timeout' => 15,
        'headers' => ['Content-Type' => 'application/json'],
        'body' => wp_json_encode([
            'token' => $token,
            'actionId' => $action_id,
            'executed' => $executed,
            'verified' => $verified,
            'error' => $error,
        ]),
    ]);

    if (is_wp_error($response)) {
        // Real, deliberate no-op beyond logging — the change was
        // already genuinely applied (or genuinely failed) on this
        // site regardless of whether Arreyon ever hears about it; a
        // failed report here shouldn't retry the write itself, since
        // WordPress-side idempotency for a partially-reported action
        // isn't something this endpoint currently guards against.
        error_log('Arreyon Connect: could not report action result back to Arreyon: ' . $response->get_error_message());
    }
}

// Real, deliberate cleanup — a scheduled cron event left behind after
// deactivation would keep firing (and keep trying to reach Arreyon)
// for a plugin the site owner just turned off.
register_deactivation_hook(__FILE__, function () {
    $scheduled = wp_next_scheduled(ARREYON_CRON_HOOK);
    if ($scheduled) {
        wp_unschedule_event($scheduled, ARREYON_CRON_HOOK);
    }
});

// ── UPDATE NOTICE ──────────────────────────────────────────────────────────
// When a newer version of this plugin is published, a notice appears on this plugin's own page and under its row on the
// Plugins screen, with a button to download it. Nothing is installed automatically: you download the file and install it
// yourself (Plugins → Add New → Upload Plugin; WordPress offers to replace the current version and your connection stays
// in place). The only thing asked of Arreyon is a short public page listing the newest version numbers — no account,
// login or site information is sent — and the answer is remembered for 12 hours (1 hour if Arreyon could not be reached).
define('ARREYON_CONNECT_VERSION', '${ARREYON_CONNECT_PLUGIN_VERSION}');
define('ARREYON_CONNECT_VERSIONS_CACHE_KEY', 'arreyon_connect_latest_version');

function arreyon_connect_is_french() {
    return strpos((string) get_locale(), 'fr') === 0;
}

function arreyon_connect_latest_version() {
    $cached = get_transient(ARREYON_CONNECT_VERSIONS_CACHE_KEY);
    if (is_string($cached)) {
        return $cached === '' ? null : $cached;
    }
    $found = '';
    $response = wp_remote_get(ARREYON_CONNECT_API_BASE . '/api/website-connector/plugin-versions', array('timeout' => 4));
    if (!is_wp_error($response) && (int) wp_remote_retrieve_response_code($response) === 200) {
        $data = json_decode(wp_remote_retrieve_body($response), true);
        $version = (is_array($data) && isset($data['connect']['version'])) ? $data['connect']['version'] : '';
        if (is_string($version) && preg_match('/^[0-9]+([.][0-9]+){0,3}$/', $version)) {
            $found = $version;
        }
    }
    set_transient(ARREYON_CONNECT_VERSIONS_CACHE_KEY, $found, $found !== '' ? 12 * HOUR_IN_SECONDS : HOUR_IN_SECONDS);
    return $found === '' ? null : $found;
}

function arreyon_connect_new_version() {
    $latest = arreyon_connect_latest_version();
    return ($latest !== null && version_compare($latest, ARREYON_CONNECT_VERSION, '>')) ? $latest : null;
}

function arreyon_connect_download_url() {
    return ARREYON_CONNECT_API_BASE . '/api/website-tools/arreyon-connect-plugin.zip';
}

function arreyon_connect_update_text($new) {
    if (arreyon_connect_is_french()) {
        return sprintf('Une nouvelle version d’Arreyon Connect est disponible : la version %1$s (vous utilisez la version %2$s). Téléchargez-la, puis allez dans Extensions → Ajouter → Téléverser une extension, choisissez le fichier et cliquez sur « Installer maintenant ». WordPress proposera de remplacer la version actuelle ; votre connexion à Arreyon est conservée.', $new, ARREYON_CONNECT_VERSION);
    }
    return sprintf('A new version of Arreyon Connect is available: version %1$s (you are using version %2$s). Download it, then go to Plugins → Add New → Upload Plugin, choose the file and click “Install Now”. WordPress will offer to replace the current version; your connection to Arreyon stays in place.', $new, ARREYON_CONNECT_VERSION);
}

// Shown at the top of this plugin's own page.
function arreyon_connect_render_update_notice() {
    $french = arreyon_connect_is_french();
    $new = arreyon_connect_new_version();
    if ($new !== null) {
        echo '<div class="notice notice-warning"><p>' . esc_html(arreyon_connect_update_text($new)) . '</p><p><a class="button button-primary" href="' . esc_url(arreyon_connect_download_url()) . '">' . esc_html($french ? 'Télécharger la version ' . $new : 'Download version ' . $new) . '</a></p></div>';
        return;
    }
    $latest = arreyon_connect_latest_version();
    $line = ($french ? 'Version ' : 'Version ') . ARREYON_CONNECT_VERSION;
    if ($latest !== null) {
        $line .= $french ? ' — vous avez la dernière version.' : ' — you have the latest version.';
    }
    echo '<p class="description">' . esc_html($line) . '</p>';
}

// Shown under this plugin's row on the Plugins screen.
add_action('after_plugin_row_' . plugin_basename(__FILE__), function () {
    if (!current_user_can('manage_options')) {
        return;
    }
    $new = arreyon_connect_new_version();
    if ($new === null) {
        return;
    }
    echo '<tr class="plugin-update-tr active"><td colspan="4" class="plugin-update colspanchange"><div class="update-message notice inline notice-warning notice-alt"><p>' . esc_html(arreyon_connect_update_text($new)) . ' <a href="' . esc_url(arreyon_connect_download_url()) . '">' . esc_html(arreyon_connect_is_french() ? 'Télécharger' : 'Download') . '</a></p></div></td></tr>';
});
`;

// Which plugin versions are the newest. Public, fixed text, no database: the plugins ask this (at most twice a day each)
// to show their "a new version is available" notice. Only version numbers are sent; each plugin builds its own download address.
app.get('/api/website-connector/plugin-versions', (req, res) => {
  res.set('Cache-Control', 'public, max-age=300');
  res.json({ connect: { version: ARREYON_CONNECT_PLUGIN_VERSION }, seoBridge: { version: ARREYON_SEO_BRIDGE_PLUGIN_VERSION } });
});

app.get('/api/website-tools/arreyon-connect-plugin.zip', (req, res) => {
  const zipBuf = arreyonBuildSingleFileZip('arreyon-connect/arreyon-connect.php', ARREYON_CONNECT_PLUGIN);
  res.setHeader('Content-Type', 'application/zip');
  res.setHeader('Content-Disposition', 'attachment; filename="arreyon-connect.zip"');
  res.send(zipBuf);
});

app.get('/api/website-tools/arreyon-connect-plugin', (req, res) => {
  res.setHeader('Content-Type', 'application/octet-stream');
  res.setHeader('Content-Disposition', 'attachment; filename="arreyon-connect.php"');
  res.send(ARREYON_CONNECT_PLUGIN);
});


// Shared by both the connect endpoint (existing business) and
// connect-new (a business created on the fly) — the actual WordPress
// verification and website_connections storage logic is identical either
// way, only how the business itself is resolved differs.
// Rather than guess which of several possible causes produced a 403,
// this reads WordPress's actual response and looks for real evidence.
// Distinguishing a genuine WordPress permission problem (a
// "rest_forbidden" JSON response — this Application Password's user
// lacks the capability the request needs) from a security plugin or
// hosting-level block matters a lot: they need completely different
// fixes, and guessing wrong wastes the person's time checking the wrong
// setting.
// Real, shared detection — the exact signature Cloudflare's own
// challenge page carries in its response body. Extracted as its own
// helper because both the human-facing error message below AND the
// automatic poll-mode fallback in connectWordPressSite need to ask
// the same real question: is this specific 403 a Cloudflare
// challenge, or something else (a security plugin, ModSecurity, wrong
// credentials)? Duplicating this check in two places risks them
// silently drifting apart over time.
function isCloudflareChallenge(bodyText) {
  const lower = (bodyText || '').toLowerCase();
  return lower.includes('just a moment') && lower.includes('cloudflare');
}

async function buildForbiddenErrorMessage(bodyText) {
  const lower = (bodyText || '').toLowerCase();

  if (lower.includes('rest_forbidden') || lower.includes('rest_cannot')) {
    return 'WordPress rejected this with a permissions error, not a security-plugin block: the WordPress user behind this Application Password does not have sufficient permissions (it needs at least an Editor role, or ideally Administrator). Please check that user\'s role in WordPress, or generate the Application Password using an Administrator account instead.';
  }

  // "Just a moment..." combined with Cloudflare's challenge markers is the
  // specific signature of Cloudflare's own bot/JS challenge page — this is
  // fundamentally different from a WAF rule or IP block, and the fix
  // depends entirely on which Cloudflare plan the site is on (researched:
  // Bot Fight Mode on the Free plan cannot be bypassed by ANY rule at
  // all — Cloudflare's own documentation is explicit about this — while
  // Super Bot Fight Mode on paid plans does support a targeted exception).
  if (isCloudflareChallenge(bodyText)) {
    return 'Cloudflare (sitting in front of this WordPress site) is showing its bot-challenge page — this happens before the request even reaches WordPress, so no WordPress or Arreyon setting can fix it directly. In the Cloudflare dashboard, check Security → Events to see exactly which feature fired. If it\'s "Bot Fight Mode" (the free-tier version), Cloudflare\'s own documentation confirms this cannot be bypassed by any rule — the only options are turning it off site-wide or upgrading to a paid plan. If it\'s "Super Bot Fight Mode" (Pro or higher) or a WAF rule, a targeted rule can be added so only authenticated REST API requests skip the challenge, e.g.: (http.request.uri.path contains "/wp-json/") and (http.request.headers["authorization"][0] ne "") — Action: Skip. This exempts only API traffic carrying real credentials, not regular visitors to the site.';
  }

  let likelySource = null;
  if (lower.includes('wordfence')) likelySource = 'Wordfence';
  else if (lower.includes('ithemes') || lower.includes('solid security')) likelySource = 'Solid Security / iThemes Security';
  else if (lower.includes('sucuri')) likelySource = 'Sucuri';
  else if (lower.includes('cloudflare')) likelySource = 'Cloudflare';
  else if (lower.includes('mod_security') || lower.includes('modsecurity')) likelySource = 'ModSecurity (a server-level firewall rule, not a WordPress plugin — your hosting provider would need to adjust this)';

  const excerpt = bodyText.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 300);

  let message = 'WordPress accepted the connection attempt but blocked it (403 Forbidden). ';
  if (likelySource) {
    message += `The response indicates this was blocked by ${likelySource}. `;
  } else {
    message += 'This is usually a security plugin or your hosting provider\'s firewall restricting REST API or Application Password access. ';
  }
  if (excerpt) {
    message += `WordPress's actual response: "${excerpt}"${excerpt.length >= 300 ? '...' : ''}`;
  }
  return message;
}

async function connectWordPressSite(businessId, siteUrl, username, appPassword, userId) {
  const trimmedUrl = siteUrl.trim();
  const trimmedUser = username.trim();
  const trimmedPass = appPassword.trim();

  let siteName = null, wpVersion = null;
  try {
    const rootRes = await wpApiRequest(trimmedUrl, '', '', '/', { timeoutMs: 8000 });
    if (rootRes.ok) {
      const rootData = await rootRes.json();
      siteName = rootData.name || null;
      wpVersion = null; // modern WordPress omits its version here by design; honestly always unavailable, not a real check
    }
  } catch (e) {
    return { ok: false, statusCode: 400, error: 'Could not reach a WordPress site at that URL. Please check the address and that the site is online.' };
  }

  let verifyRes;
  try {
    verifyRes = await wpApiRequest(trimmedUrl, trimmedUser, trimmedPass, '/wp/v2/pages?per_page=1&status=any&context=edit', { timeoutMs: 10000 });
  } catch (e) {
    return { ok: false, statusCode: 400, error: safeErrorMessage(e, 'Could not connect to WordPress. Please check your website URL.') };
  }

  if (verifyRes.status === 401) {
    return { ok: false, statusCode: 400, error: 'WordPress rejected these credentials. Please check your username and Application Password.' };
  }

  let pollingToken = null;
  let usePollMode = false;
  if (verifyRes.status === 403) {
    const bodyText = await verifyRes.text();
    if (isCloudflareChallenge(bodyText)) {
      // Real, deliberate fallback — Cloudflare is blocking this
      // authenticated request before it ever reaches WordPress, and
      // (for the free-tier Bot Fight Mode specifically) there is
      // genuinely no rule that can exempt it. Rather than fail here,
      // this site is connected in poll mode instead: its own plugin
      // will call Arreyon directly (an outbound request from the
      // site, never subject to Bot Fight Mode, which only inspects
      // INBOUND traffic) and execute approved changes locally.
      usePollMode = true;
      pollingToken = crypto.randomBytes(32).toString('hex');
    } else {
      return { ok: false, statusCode: 400, error: await buildForbiddenErrorMessage(bodyText) };
    }
  } else if (!verifyRes.ok) {
    return { ok: false, statusCode: 400, error: `WordPress returned an unexpected error (status ${verifyRes.status}). Please verify your site supports the REST API.` };
  }

  const encryptedPassword = encryptSecret(trimmedPass);
  const pollingTokenHash = pollingToken ? crypto.createHash('sha256').update(pollingToken).digest('hex') : null;
  const connectionMode = usePollMode ? 'poll' : 'push';

  const existing = await pool.query('SELECT id FROM website_connections WHERE business_id = $1', [businessId]);
  let connection;
  if (existing.rows.length) {
    const updated = await pool.query(
      `UPDATE website_connections SET site_url = $1, site_name = $2, wp_version = $3, wp_username = $4,
       wp_app_password_encrypted = $5, connection_status = 'connected', last_verified_at = NOW(),
       last_error = NULL, connected_at = NOW(), disconnected_at = NULL, connection_mode = $6, polling_token_hash = $7
       WHERE id = $8 RETURNING id, site_url, site_name, connection_status, permission_level, automation_mode, connected_at, connection_mode`,
      [trimmedUrl, siteName, wpVersion, trimmedUser, encryptedPassword, connectionMode, pollingTokenHash, existing.rows[0].id]
    );
    connection = updated.rows[0];
  } else {
    const inserted = await pool.query(
      `INSERT INTO website_connections (business_id, site_url, site_name, wp_version, wp_username, wp_app_password_encrypted, connection_status, last_verified_at, connected_at, connection_mode, polling_token_hash)
       VALUES ($1, $2, $3, $4, $5, $6, 'connected', NOW(), NOW(), $7, $8)
       RETURNING id, site_url, site_name, connection_status, permission_level, automation_mode, connected_at, connection_mode`,
      [businessId, trimmedUrl, siteName, wpVersion, trimmedUser, encryptedPassword, connectionMode, pollingTokenHash]
    );
    connection = inserted.rows[0];
  }

  await logWebsiteAudit(connection.id, 'user', userId,
    usePollMode ? 'connected_poll_mode' : 'connected',
    usePollMode
      ? `Connected WordPress site in poll mode (Cloudflare blocked the direct connection): ${trimmedUrl}`
      : `Connected WordPress site: ${trimmedUrl}`,
    { siteUrl: trimmedUrl }, 'connection');

  // pollingToken (plaintext) is only ever returned here, once, at the
  // moment it's generated — same discipline as the Application
  // Password itself never being returned to the frontend after
  // creation. The plugin is the only other party that ever needs it,
  // and only right now to store it for itself.
  return { ok: true, connection, pollingToken };
}

// Connects a WordPress site to a business that hasn't been analyzed yet —
// creates a minimal business record first (name only; every other
// businesses column is nullable, so this is a safe, valid row), so a
// website can be connected without requiring the full Analyzer flow to
// run beforehand.
app.post('/api/business/website/connect-new', authRequired, async (req, res) => {
  const { businessName, siteUrl, username, appPassword } = req.body;
  if (!businessName || !businessName.trim()) return res.status(400).json({ error: 'Please enter a business name.' });
  if (!siteUrl || !siteUrl.trim()) return res.status(400).json({ error: 'Please enter your website URL.' });
  if (!username || !username.trim()) return res.status(400).json({ error: 'Please enter your WordPress username.' });
  if (!appPassword || !appPassword.trim()) return res.status(400).json({ error: 'Please enter your Application Password.' });

  try {
    const account = await resolveAccount(req.userId);
    const inserted = await pool.query(
      'INSERT INTO businesses (user_id, name, website) VALUES ($1, $2, $3) RETURNING id',
      [account.id, businessName.trim(), siteUrl.trim()]
    );
    const newBusinessId = inserted.rows[0].id;

    const result = await connectWordPressSite(newBusinessId, siteUrl, username, appPassword, req.userId);
    if (!result.ok) {
      // The business now exists even though the connection attempt
      // failed — that's the right outcome (it's a real, correctly-named
      // business the person can retry connecting from the normal
      // dropdown), not something to roll back just because this one step
      // didn't succeed.
      return res.status(result.statusCode).json({ error: result.error, businessId: newBusinessId });
    }

    res.json({ success: true, businessId: newBusinessId, connection: result.connection });
  } catch (e) {
    console.error('Website connect-new error:', e.message);
    res.status(500).json({ error: 'Failed to connect website' });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// ARREYON CONNECT PLUGIN — connection-code handshake (Option 2). Arreyon
// generates a short-lived, single-use code and displays it; the person
// enters that code into the Arreyon Connect plugin on their own WordPress
// site, which then reaches OUT to Arreyon (the reverse of the direct
// credential flow) with a fresh Application Password it generated itself.
// Excludes visually ambiguous characters (0/O, 1/I/L) since a person needs
// to type this by hand from one screen into another.
// ═══════════════════════════════════════════════════════════════════════════
function generateConnectionCode() {
  const chars = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  const segment = (len) => Array.from({ length: len }, () => chars[crypto.randomInt(chars.length)]).join('');
  return `ARREYON-${segment(4)}-${segment(4)}`;
}

async function generateAndStoreConnectionCode(businessId) {
  // Only one live code per business at a time — expiring any earlier,
  // still-unused code for this business avoids confusion about which of
  // several displayed codes is actually still valid.
  await pool.query(`UPDATE website_connection_codes SET expires_at = NOW() WHERE business_id = $1 AND used_at IS NULL`, [businessId]);

  const code = generateConnectionCode();
  const expiresAt = new Date(Date.now() + 15 * 60 * 1000); // 15 minutes — long enough to switch tabs and install a plugin, short enough to keep the guessing window small
  await pool.query(
    'INSERT INTO website_connection_codes (business_id, code, expires_at) VALUES ($1, $2, $3)',
    [businessId, code, expiresAt]
  );
  return { code, expiresAt };
}

app.post('/api/business/:id/website/generate-code', authRequired, async (req, res) => {
  try {
    const account = await resolveAccount(req.userId);
    const biz = await pool.query('SELECT id FROM businesses WHERE id = $1 AND user_id = $2', [req.params.id, account.id]);
    if (!biz.rows.length) return res.status(404).json({ error: 'Business not found' });

    const { code, expiresAt } = await generateAndStoreConnectionCode(req.params.id);
    res.json({ code, expiresAt });
  } catch (e) {
    console.error('Generate connection code error:', e.message);
    res.status(500).json({ error: 'Failed to generate a connection code' });
  }
});

// Same as above, but for a business that hasn't been analyzed yet —
// creates a minimal business record first (name only, same as
