  const ctx = await wordpressReportRouteContext(req); if (ctx.failure) return { status: ctx.status, body: ctx.failure };
  if (!WORDPRESS_UUID_RX.test(req.params.reportId)) return { status: 404, body: wordpressFail('report_not_found') };
  const row = (await pool.query('SELECT id, kind, period_start::text AS period_start, period_end::text AS period_end, content, created_at FROM wordpress_reports WHERE id = $1 AND website_connection_id = $2', [req.params.reportId, ctx.connection.id])).rows[0]; return row ? { row, connection: ctx.connection } : { status: 404, body: wordpressFail('report_not_found') };
