// Real, deliberate stage-1 scope — reuses the exact same real readability,
// anti-hallucination, and punctuation rules already proven for WordPress,
// but external links only; a real Shopify page/article fetch for internal
// link candidates is real, separate stage-2 work, disclosed honestly
// rather than silently built as if it already existed.
// Real, deliberate same verification discipline as WordPress's internal
// candidates — a real page or article is only ever offered as a link
// candidate once its real URL has actually been checked to resolve, not
// constructed and assumed. This is what internal links for Shopify were
// explicitly missing when the Shopify integration first shipped.
async function getShopifyContentForAnalysis(connection, accessToken) {
  const candidates = [];
  const storeUrl = await getShopifyStoreUrl(connection, accessToken);

  // Real, deliberate real blog handle lookup — a Shopify store's blog is
  // not always named "news"; assuming that would silently construct
  // real, broken links for any store that renamed or added a blog.
  let blogHandle = 'news';
  try {
    if (connection.blog_id) {
      const blogRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/blogs/${connection.blog_id}.json`);
      if (blogRes.ok) { const d = await blogRes.json(); blogHandle = d.blog?.handle || blogHandle; }
    }
  } catch (e) { /* Real, deliberate fallback to the default handle — verification below still catches a wrong guess. */ }

  try {
    if (connection.blog_id) {
      const articlesRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/blogs/${connection.blog_id}/articles.json?limit=20&fields=title,handle`);
      if (articlesRes.ok) {
        const d = await articlesRes.json();
        for (const a of (d.articles || [])) {
          candidates.push({ title: a.title, url: `${storeUrl}/blogs/${blogHandle}/${a.handle}` });
        }
      }
    }
  } catch (e) { /* Real, deliberate no-op — proceeds with whatever real candidates were found. */ }

  try {
    const pagesRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/pages.json?limit=20&fields=title,handle`);
    if (pagesRes.ok) {
      const d = await pagesRes.json();
      for (const p of (d.pages || [])) {
        candidates.push({ title: p.title, url: `${storeUrl}/pages/${p.handle}` });
      }
    }
  } catch (e) { /* Real, deliberate no-op. */ }

  // Real, deliberate live verification of every real candidate — the
  // same real discipline WordPress's internal candidates already use,
  // never trusting a constructed URL just because the pieces look right.
  const verified = await Promise.all(candidates.map(async (c) => ({ ...c, resolves: !(await checkInternalLinkResolves(c.url)).broken })));
  return verified.filter(c => c.resolves).slice(0, 15);
}

// Real, deliberate word-count and real meta-tag presence check, the
// richer analysis Website Intelligence needs beyond what the internal-
// link candidates above require. Capped to a reasonable real sample
// (8 articles, 8 pages) since each real meta-tag check is its own real
// API call — unbounded would mean dozens of real requests for a single
// on-demand analysis.
async function getShopifyContentForIntelligence(connection, accessToken) {
  const storeUrl = await getShopifyStoreUrl(connection, accessToken);
  let blogHandle = 'news';
  try {
    if (connection.blog_id) {
      const blogRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/blogs/${connection.blog_id}.json`);
      if (blogRes.ok) { const d = await blogRes.json(); blogHandle = d.blog?.handle || blogHandle; }
    }
  } catch (e) { /* Real, deliberate fallback. */ }

  // Real, deliberate single metafields lookup per real resource — the
  // only way Shopify's REST API exposes a real article's or page's own
  // real title_tag/description_tag values.
  // Real, deliberate single real metafields call returning both real SEO
  // fields — the response already contains every real metafield for this
  // resource, so filtering for both title_tag and description_tag here
  // costs nothing extra over filtering for just one.
  async function fetchSeoMetafields(resourceType, resourceId) {
    try {
      const res = await shopifyApiRequest(connection.shop_domain, accessToken, `/${resourceType}/${resourceId}/metafields.json`);
      if (!res.ok) return { metaTitle: null, metaDescription: null };
      const d = await res.json();
      const metafields = d.metafields || [];
      const metaTitle = metafields.find(m => m.namespace === 'global' && m.key === 'title_tag')?.value || null;
      const metaDescription = metafields.find(m => m.namespace === 'global' && m.key === 'description_tag')?.value || null;
      return { metaTitle, metaDescription };
    } catch (e) { return { metaTitle: null, metaDescription: null }; }
  }

  function wordCount(html) {
    return (html || '').replace(/<[^>]+>/g, ' ').split(/\s+/).filter(Boolean).length;
  }
  function excerpt(html) {
    return (html || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 400);
  }

  const items = [];
  let totalArticleCount = 0, totalPageCount = 0;

  try {
    if (connection.blog_id) {
      const countRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/blogs/${connection.blog_id}/articles/count.json`);
      if (countRes.ok) { const d = await countRes.json(); totalArticleCount = d.count || 0; }
      const articlesRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/blogs/${connection.blog_id}/articles.json?limit=8&fields=id,title,handle,body_html`);
      if (articlesRes.ok) {
        const d = await articlesRes.json();
        for (const a of (d.articles || [])) {
          const { metaTitle, metaDescription } = await fetchSeoMetafields('articles', a.id);
          items.push({ type: 'post', id: a.id, title: a.title, url: `${storeUrl}/blogs/${blogHandle}/${a.handle}`, wordCount: wordCount(a.body_html), bodyExcerpt: excerpt(a.body_html), bodyHtml: a.body_html, metaTitle, metaDescription });
        }
      }
    }
  } catch (e) { /* Real, deliberate no-op — proceeds with whatever was found. */ }

  try {
    const pageCountRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/pages/count.json`);
    if (pageCountRes.ok) { const d = await pageCountRes.json(); totalPageCount = d.count || 0; }
    const pagesRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/pages.json?limit=8&fields=id,title,handle,body_html`);
    if (pagesRes.ok) {
      const d = await pagesRes.json();
      for (const p of (d.pages || [])) {
        const { metaTitle, metaDescription } = await fetchSeoMetafields('pages', p.id);
        items.push({ type: 'page', id: p.id, title: p.title, url: `${storeUrl}/pages/${p.handle}`, wordCount: wordCount(p.body_html), bodyExcerpt: excerpt(p.body_html), bodyHtml: p.body_html, metaTitle, metaDescription });
      }
    }
  } catch (e) { /* Real, deliberate no-op. */ }

  return { items, totalArticleCount, totalPageCount };
}

// Real, deliberate same structure and same critical rules as the
// WordPress version — the real measured data changes (it's Shopify's
// own real pages/articles now), but the same real discipline applies:
// every issue has to reference something actually present in that data.
async function runShopifyWebsiteIntelligence(connection, accessToken, businessName) {
  const { items, totalArticleCount, totalPageCount } = await getShopifyContentForIntelligence(connection, accessToken);
  if (!items.length) return;

  const itemsSummary = items.map(i => `${i.type.toUpperCase()}: "${i.title}" (${i.url})\n  Word count: ${i.wordCount} | Meta description: ${i.metaDescription ? `"${i.metaDescription}"` : 'NOT DETECTED'}\n  Excerpt: ${i.bodyExcerpt}`).join('\n\n');

  const prompt = `You are a website intelligence analyst reviewing a Shopify store for ${businessName || 'this business'}. You have been given REAL, MEASURED data fetched directly from the store's own content — word counts and meta description presence are FACTS, not your opinion.

MEASURED DATA (${items.length} of ${totalArticleCount + totalPageCount} total pages/articles):
${itemsSummary}

CRITICAL RULES:
- Every issue must reference something ACTUALLY PRESENT in the measured data above — never invent a page, a number, or an issue not grounded in what's shown.
- Do NOT invent a numeric "website score."
- Thin content threshold: under 300 words is a genuine concern; do not flag naturally short pages as broken just for being short.
- Limit output to AT MOST 15 seo_issues, 10 content_observations, and 8 recommendations, prioritizing the most significant findings.

Return ONLY valid JSON, no markdown, in exactly this structure:
{
  "structure_summary": "2-3 sentences on what this store's content actually consists of",
  "seo_issues": [{ "page_title": "exact title", "url": "exact url", "issue": "specific issue", "severity": "high" | "medium" | "low" }],
  "content_observations": [{ "page_title": "exact title", "observation": "specific observation" }],
  "recommendations": [{ "title": "short action title", "description": "1-2 sentences", "priority": "high" | "medium" | "low" }],
  "data_limitations_note": "one honest sentence on what this analysis could NOT see"
}`;

  const raw = await callAI({ persona: prompt, messages: [{ role: 'user', content: 'Provide the Website Intelligence analysis now, as JSON only.' }], complexity: 'complex', context: { feature: 'shopify_website_intelligence' }, maxTokens: 8000 });

  let intelligence;
  try {
    intelligence = extractJSON(raw);
  } catch (e) {
    throw new Error(`Website Intelligence failed to parse: ${e.message}`);
  }
  if (!Array.isArray(intelligence.seo_issues) || !Array.isArray(intelligence.recommendations)) {
    throw new Error('Website Intelligence returned incomplete data.');
  }

  intelligence.seo_issues = intelligence.seo_issues.slice(0, 15);
  if (Array.isArray(intelligence.content_observations)) intelligence.content_observations = intelligence.content_observations.slice(0, 10);
  intelligence.recommendations = intelligence.recommendations.slice(0, 8);
  intelligence.measured = {
    pageCount: totalPageCount, postCount: totalArticleCount,
    analyzedPageCount: items.filter(i => i.type === 'page').length, analyzedPostCount: items.filter(i => i.type === 'post').length,
    pagesWithNoMetaDescription: items.filter(i => !i.metaDescription).length,
    pagesUnder300Words: items.filter(i => i.wordCount < 300).length,
  };

  await pool.query(
    `UPDATE shopify_connections SET website_intelligence = $1, website_intelligence_fr = NULL, website_intelligence_generated_at = NOW() WHERE id = $2`,
    [JSON.stringify(intelligence), connection.id]
  );
  return intelligence;
}

// Real, deliberate leaner Shopify equivalent of WordPress's Run Audit &
// Optimize — real meta-tag gaps and real broken internal links only, no
// category/tag actions (Shopify has no real taxonomy equivalent to
// propose against), and every real proposal here requires manual
// approval: Shopify has no permission/automation settings of its own
// yet, so auto-execution would have no real, user-controlled gate to
// check against. A disclosed, honest scope boundary for this first
// real version, not a silent omission.
// shopify-own:start
// ── Shopify: audit history and activity log ──────────────────────────────────────────────────────────────────────────────────────────
// The activity log says who did what to the store, grouped by feature. Each entry stores the FACTS (what kind of change, which page, how many) as well as an English
// sentence; the dashboard builds the sentence again in the person's own language, so the log reads correctly in French or English whenever it is opened.
// A log write NEVER breaks the thing it describes: if it fails, the failure is noted on the server and the action goes on. Only the LOG is ever cleared from the
// dashboard; the changes themselves, posts and saved results are never touched.
const SHOPIFY_LOG_FEATURES = ['seo_proposals', 'taxonomy', 'duplicate_titles', 'broken_links', 'featured_images', 'content_generation', 'intelligence', 'connection', 'general'];
async function logShopifyAudit(connectionId, actorType, actorId, actionType, description, details, feature = 'general') {
  try {
    await pool.query(`INSERT INTO shopify_audit_log (shopify_connection_id, actor_type, actor_id, action_type, description, details, feature) VALUES ($1, $2, $3, $4, $5, $6, $7)`,
      [connectionId, actorType, actorId && SHOPIFY_UUID_RX.test(String(actorId)) ? actorId : null, String(actionType).slice(0, 50), String(description || actionType).slice(0, 500), JSON.stringify(details || {}), SHOPIFY_LOG_FEATURES.includes(feature) ? feature : 'general']);
  } catch (e) { console.error('Shopify activity log write failed:', e.message); }
}
function shopifyFeatureForActionType(type) {
  if (type === 'update_meta_title' || type === 'update_meta_description') return 'seo_proposals';
  if (type === 'add_tags') return 'taxonomy';
  if (type === 'generate_featured_image') return 'featured_images';
  if (type === 'remove_broken_link' || type === 'update_link_url') return 'broken_links';
  if (SHOPIFY_CONTENT_TYPES.includes(type)) return 'seo_proposals';
  if (SHOPIFY_ALT_TYPES.includes(type)) return 'seo_proposals';
  if (SHOPIFY_INLINK_TYPES.includes(type)) return 'seo_proposals';
  return 'general';
}
// What a proposed change IS, as facts (kind, value, page) rather than a sentence, so the dashboard can say it in any language.
function shopifyChangeParts(action) {
  const c = action.proposed_change || {}, t = action.action_type, targetTitle = action.target_title || '';
  if (t === 'update_meta_title') return { kind: 'meta_title', value: c.metaTitle || '', targetTitle };
  if (t === 'update_meta_description') return { kind: 'meta_description', value: c.metaDescription || '', targetTitle };
  if (t === 'add_tags') return { kind: 'tags', value: (Array.isArray(c.tags) ? c.tags : []).join(', '), targetTitle };
  if (t === 'generate_featured_image') return { kind: 'featured_image', value: '', targetTitle };
  if (t === 'remove_broken_link') return { kind: 'remove_link', value: c.brokenUrl || '', targetTitle };
  if (t === 'update_link_url') return { kind: 'change_link', value: c.oldUrl || '', to: c.newUrl || '', targetTitle };
  if (t === 'expand_thin_content') return { kind: 'expand_content', value: String(c.addedWords || 0), targetTitle };
  if (t === 'fix_heading_levels') return { kind: 'heading_levels', value: String((c.headingLevels || []).length), targetTitle };
  if (t === 'add_subheadings') return { kind: 'subheadings', value: String((c.subheadings || []).length), targetTitle };
  if (t === 'fix_content_image_alt') return { kind: 'alt_content', value: String((Array.isArray(c.images) ? c.images : []).length), targetTitle };
  if (t === 'add_internal_links') return { kind: 'internal_links', value: String((c.links || []).length), targetTitle };
  return { kind: 'other', value: t || '', targetTitle };
}
const SHOPIFY_CHANGE_ENGLISH = { meta_title: p => `Meta title: "${p.value}"`, meta_description: p => `Meta description: "${p.value}"`, tags: p => `Add tags: ${p.value}`, featured_image: () => 'Featured image', expand_content: p => `Add ${p.value} words of new content`, heading_levels: p => `Fix ${p.value} heading level(s)`, subheadings: p => `Add ${p.value} subheading(s)`, alt_content: p => `Add ${p.value} image description(s)`, remove_link: p => `Remove broken link to ${p.value}`, change_link: p => `Change link ${p.value} to ${p.to}`, internal_links: p => `Add ${p.value} internal link(s)`, other: p => p.value || 'Change' };
const shopifyChangeLabel = action => { const p = shopifyChangeParts(action); return `${SHOPIFY_CHANGE_ENGLISH[p.kind](p)}${p.targetTitle ? ` on "${p.targetTitle}"` : ''}`; };
// What happened when a person approved a change.
async function logShopifyChangeDecision(connection, action, userId, exec) {
  const label = shopifyChangeLabel(action), feature = shopifyFeatureForActionType(action.action_type), details = { actionId: action.id, actionType: action.action_type, change: shopifyChangeParts(action) };
  if (exec.executed) return logShopifyAudit(connection.id, 'user', userId, exec.verified === false ? 'change_applied_unverified' : 'change_applied', `${exec.verified === false ? 'Applied, but could not be verified' : 'Applied'}: ${label}`, details, feature);
  return logShopifyAudit(connection.id, 'user', userId, 'change_failed', `Could not apply: ${label}`, { ...details, error: String(exec.error || '').slice(0, 300), errorCode: exec.errorCode || null, errorParams: exec.errorParams || null }, feature);
}
// A suggestion run by a person: one line for the run, one for each change the store applied by itself.
const SHOPIFY_RUN_WORDS = { tags: ['taxonomy', 'Looked for posts without tags'], duplicate_titles: ['duplicate_titles', 'Looked for duplicate titles'], featured_images: ['featured_images', 'Looked for articles without a featured image'], thin_content: ['seo_proposals', 'Looked for thin pages'], headings: ['seo_proposals', 'Looked at page headings'], alt_content: ['seo_proposals', 'Looked for pictures without a description'], inlinks: ['seo_proposals', 'Looked for pages that need internal links'] };
async function logShopifyProposalRun(connection, userId, what, out) {
  const [feature, words] = SHOPIFY_RUN_WORDS[what] || ['general', 'Looked for improvements'];
  const proposals = Array.isArray(out && out.proposals) ? out.proposals : [], auto = proposals.filter(p => p.execution_status === 'executed');
  await logShopifyAudit(connection.id, 'user', userId, 'proposals_generated', proposals.length ? `${words}: ${proposals.length} proposal(s) made${auto.length ? `, ${auto.length} applied automatically` : ''}` : `${words}: nothing to propose`, { what, count: proposals.length, autoApplied: auto.length }, feature);
  for (const a of auto) await logShopifyAudit(connection.id, 'system', null, 'change_auto_applied', `Applied automatically: ${shopifyChangeLabel(a)}`, { actionId: a.id, actionType: a.action_type, change: shopifyChangeParts(a) }, shopifyFeatureForActionType(a.action_type));
}
// The audit's result in the shape the history card shows: totals, a found/fixed/waiting line per kind of problem, and what happened to each page (as facts).
function shopifyAuditSummary(result) {
  const f = (result && result.foundIssues) || {}, fixed = (result && result.autoApplied) || [], pending = (result && result.proposalsCreated) || [];
  const bucket = a => a.action_type === 'update_meta_title' ? 'metaTitle' : a.action_type === 'update_meta_description' ? 'metaDescription' : 'brokenLinks';
  const findings = {};
  for (const key of ['metaTitle', 'metaDescription', 'brokenLinks']) {
    const fx = fixed.filter(a => bucket(a) === key).length, pd = pending.filter(a => bucket(a) === key).length, found = Number(f[key]) || 0;
    if (found || fx || pd) findings[key] = { found, fixed: fx, pending: pd };
  }
  const pages = new Map(), add = (a, status) => {
    const k = `${a.target_type}:${a.target_shopify_id}`, p = shopifyChangeParts(a); if (!pages.has(k)) pages.set(k, { title: a.target_title || '', url: a.target_url || '', changes: [] });
    pages.get(k).changes.push({ kind: p.kind, value: p.value, ...(p.to ? { to: p.to } : {}), description: SHOPIFY_CHANGE_ENGLISH[p.kind](p), status });
  };
  fixed.forEach(a => add(a, 'fixed')); pending.forEach(a => add(a, 'pending'));
  return { issuesFound: Object.values(f).reduce((n, v) => n + (Number(v) || 0), 0), autoFixed: fixed.length, pending: pending.length, findings: { ...findings, byPage: [...pages.values()] } };
}
// Runs the audit and keeps a record of it (running, then completed or failed). The record is bookkeeping: if saving it fails, the audit itself is not affected.
async function runShopifyAuditRecorded(connection, accessToken, context, userId, triggeredBy) {
  let runId = null; const actor = triggeredBy === 'automatic' ? 'system' : 'user';
  try { runId = (await pool.query(`INSERT INTO shopify_audit_runs (shopify_connection_id, triggered_by, status) VALUES ($1, $2, 'running') RETURNING id`, [connection.id, triggeredBy])).rows[0].id; }
  catch (e) { console.error('Shopify audit run could not be recorded:', e.message); }
  let result;
  try { result = await runShopifyAudit(connection, accessToken, context, userId); }
  catch (e) {
    if (runId) await pool.query(`UPDATE shopify_audit_runs SET status = 'failed', error_message = $1, completed_at = NOW() WHERE id = $2`, [safeErrorMessage(e, 'The audit could not be completed.'), runId]).catch(() => {});
    await logShopifyAudit(connection.id, actor, userId, 'audit_run_failed', 'Audit run failed', { runId }, 'general');
    throw e;
  }
  try {
    const sum = shopifyAuditSummary(result);
    if (runId) await pool.query(`UPDATE shopify_audit_runs SET status = 'completed', issues_found_count = $1, auto_fixed_count = $2, pending_approval_count = $3, findings_summary = $4, completed_at = NOW() WHERE id = $5`, [sum.issuesFound, sum.autoFixed, sum.pending, JSON.stringify(sum.findings), runId]);
    for (const a of result.autoApplied || []) await logShopifyAudit(connection.id, 'system', null, 'change_auto_applied', `Applied automatically: ${shopifyChangeLabel(a)}`, { actionId: a.id, actionType: a.action_type, change: shopifyChangeParts(a), runId }, shopifyFeatureForActionType(a.action_type));
    await logShopifyAudit(connection.id, actor, userId, 'audit_run_completed', `Audit run completed: ${sum.issuesFound} issue(s) found, ${sum.autoFixed} auto-fixed, ${sum.pending} awaiting approval`, { runId, issuesFound: sum.issuesFound, autoFixed: sum.autoFixed, pendingApproval: sum.pending }, 'general');
  } catch (e) {
    console.error('Shopify audit record could not be completed:', e.message);
    if (runId) await pool.query(`UPDATE shopify_audit_runs SET status = 'completed', error_message = 'The details of this run could not be recorded.', completed_at = NOW() WHERE id = $1 AND status = 'running'`, [runId]).catch(() => {});   // the audit itself worked: never leave it showing as running
  }
  return { ...result, runId };
}
// Routes: the list of audit runs, and clearing it; the activity log, and clearing it (selected entries, one feature, or everything).
async function shopifyConnectionIdForRequest(req) {
  if (!(await userOwnsBusiness(req))) return { status: 404, failure: shopifyFail('business_not_found') };
  const row = (await pool.query('SELECT id FROM shopify_connections WHERE business_id = $1', [req.params.id])).rows[0];
  return row ? { id: row.id } : { id: null };
}
const shopifyValidIds = list => Array.isArray(list) && list.length > 0 && list.length <= 500 && list.every(x => SHOPIFY_UUID_RX.test(String(x)));
app.get('/api/business/:id/shopify/audit-runs', authRequired, async (req, res) => {
  try {
    const c = await shopifyConnectionIdForRequest(req); if (c.failure) return res.status(c.status).json(c.failure);
    if (!c.id) return res.json({ runs: [] });
    res.json({ runs: (await pool.query('SELECT * FROM shopify_audit_runs WHERE shopify_connection_id = $1 ORDER BY started_at DESC LIMIT 50', [c.id])).rows });
  } catch (e) { console.error('Get Shopify audit runs error:', e.message); res.status(500).json(shopifyFail('runs_load_failed')); }
});
app.delete('/api/business/:id/shopify/audit-runs', authRequired, async (req, res) => {
  try {
    const c = await shopifyConnectionIdForRequest(req); if (c.failure) return res.status(c.status).json(c.failure);
    if (!c.id) return res.status(404).json(shopifyFail('no_store'));
    const { ids, all } = req.body || {};
    if (ids !== undefined) { if (!shopifyValidIds(ids)) return res.status(400).json(shopifyFail('runs_invalid')); return res.json({ success: true, clearedCount: (await pool.query('DELETE FROM shopify_audit_runs WHERE shopify_connection_id = $1 AND id = ANY($2::uuid[]) RETURNING id', [c.id, ids])).rows.length }); }
    if (all === true) return res.json({ success: true, clearedCount: (await pool.query('DELETE FROM shopify_audit_runs WHERE shopify_connection_id = $1 RETURNING id', [c.id])).rows.length });
    res.status(400).json(shopifyFail('runs_specify'));
  } catch (e) { console.error('Clear Shopify audit runs error:', e.message); res.status(500).json(shopifyFail('runs_clear_failed')); }
});
app.get('/api/business/:id/shopify/activity-log', authRequired, async (req, res) => {
  try {
    const c = await shopifyConnectionIdForRequest(req); if (c.failure) return res.status(c.status).json(c.failure);
    const feature = req.query.feature && req.query.feature !== 'all' ? String(req.query.feature) : null;
    if (feature && !SHOPIFY_LOG_FEATURES.includes(feature)) return res.status(400).json(shopifyFail('log_unknown_feature'));
    if (!c.id) return res.json({ entries: [], featureCounts: [] });
    const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 100, 1), 200), cols = 'id, actor_type, actor_id, action_type, description, details, feature, created_at';
    const rows = feature ? await pool.query(`SELECT ${cols} FROM shopify_audit_log WHERE shopify_connection_id = $1 AND feature = $2 ORDER BY created_at DESC LIMIT $3`, [c.id, feature, limit]) : await pool.query(`SELECT ${cols} FROM shopify_audit_log WHERE shopify_connection_id = $1 ORDER BY created_at DESC LIMIT $2`, [c.id, limit]);
    res.json({ entries: rows.rows, featureCounts: (await pool.query('SELECT feature, COUNT(*)::int AS count FROM shopify_audit_log WHERE shopify_connection_id = $1 GROUP BY feature', [c.id])).rows });
  } catch (e) { console.error('Get Shopify activity log error:', e.message); res.status(500).json(shopifyFail('log_load_failed')); }
});
app.delete('/api/business/:id/shopify/activity-log', authRequired, async (req, res) => {
  try {
    const c = await shopifyConnectionIdForRequest(req); if (c.failure) return res.status(c.status).json(c.failure);
    if (!c.id) return res.status(404).json(shopifyFail('no_store'));
    const { ids, feature, all } = req.body || {};   // exactly one of three explicit modes, never an ambiguous default that could clear more than was asked
    if (ids !== undefined) { if (!shopifyValidIds(ids)) return res.status(400).json(shopifyFail('log_invalid')); return res.json({ success: true, clearedCount: (await pool.query('DELETE FROM shopify_audit_log WHERE shopify_connection_id = $1 AND id = ANY($2::uuid[]) RETURNING id', [c.id, ids])).rows.length }); }
    if (feature !== undefined && feature !== 'all') { if (!SHOPIFY_LOG_FEATURES.includes(feature)) return res.status(400).json(shopifyFail('log_unknown_feature')); return res.json({ success: true, clearedCount: (await pool.query('DELETE FROM shopify_audit_log WHERE shopify_connection_id = $1 AND feature = $2 RETURNING id', [c.id, feature])).rows.length }); }
    if (all === true || feature === 'all') return res.json({ success: true, clearedCount: (await pool.query('DELETE FROM shopify_audit_log WHERE shopify_connection_id = $1 RETURNING id', [c.id])).rows.length });
    res.status(400).json(shopifyFail('log_specify'));
  } catch (e) { console.error('Clear Shopify activity log error:', e.message); res.status(500).json(shopifyFail('log_clear_failed')); }
});

// shopify-own:end
async function runShopifyAudit(connection, accessToken, context, userId = null) {
  const { items } = await getShopifyContentForIntelligence(connection, accessToken);
  const auditStoreUrl = await getShopifyStoreUrl(connection, accessToken);
  const foundIssues = { metaTitle: 0, metaDescription: 0, brokenLinks: 0 };
  const proposalsCreated = [];
  const autoApplied = [];
  // Automatic mode is the owner's standing permission for the low-risk tier
  // only (meta title/description). Content edits like removing a link always wait.

  // Real, deliberate real meta-tag gap detection — only items genuinely
  // missing a real title_tag or description_tag, never a judgment call
  // about whether an existing one is "good enough."
  const metaCandidates = items.filter(i => !i.metaTitle || !i.metaDescription);
  if (metaCandidates.length) {
    const contextSummary = summarizeBusinessContextForAI(context) || 'No detailed context is available for this business yet.';
    const candidatesSummary = metaCandidates.map((c, i) => `[${i}] ${c.type.toUpperCase()}: "${c.title}" (${c.url})\n  Current meta title: ${c.metaTitle ? `"${c.metaTitle}"` : 'MISSING'}\n  Current meta description: ${c.metaDescription ? `"${c.metaDescription}"` : 'MISSING'}\n  Content excerpt: ${c.bodyExcerpt}`).join('\n\n');

    const prompt = `You are an SEO Agent proposing meta title and description improvements for a real Shopify store. Every candidate listed below already has a real, measured gap (a missing meta title or description) — you need to write GOOD, SPECIFIC suggestions grounded in the actual page content and the real business context, not generic boilerplate.
${contextSummary}

PAGES/ARTICLES NEEDING ATTENTION:
${candidatesSummary}

For EACH numbered item above that is MISSING a meta title, propose a suggested_title (50-60 characters). For each MISSING a meta description, propose a suggested_meta_description (120-155 characters). Leave the other field null if it already exists. Reference the actual business name/industry where it genuinely fits — never invent details not in the context above.

Return ONLY valid JSON, no markdown:
{ "proposals": [{ "index": 0, "suggested_title": "... or null", "suggested_meta_description": "... or null", "reasoning": "1 sentence on why this helps" }] }`;

    try {
      const raw = await callAI({ persona: prompt, messages: [{ role: 'user', content: 'Provide the proposals now, as JSON only.' }], complexity: 'complex', context: { feature: 'shopify_seo_proposals', userId }, maxTokens: 4000 });
      const result = extractJSON(raw);
      if (Array.isArray(result.proposals)) {
        for (const p of result.proposals) {
          const candidate = metaCandidates[p.index];
          if (!candidate || (!p.suggested_title && !p.suggested_meta_description)) continue;

          const actionType = p.suggested_title ? 'update_meta_title' : 'update_meta_description';
          const proposedChange = {};
          if (p.suggested_title) proposedChange.metaTitle = p.suggested_title;
          if (p.suggested_meta_description) proposedChange.metaDescription = p.suggested_meta_description;
          foundIssues[p.suggested_title ? 'metaTitle' : 'metaDescription']++;

          // Real, deliberate dedup — never a second real pending
          // proposal of the same real type for the same real target.
          const existing = await pool.query(
            `SELECT id FROM shopify_actions WHERE shopify_connection_id = $1 AND target_shopify_id = $2 AND action_type = $3 AND approval_status = 'pending'`,
            [connection.id, candidate.id, actionType]
          );
          if (existing.rows.length) continue;

          const inserted = await pool.query(
            `INSERT INTO shopify_actions (shopify_connection_id, action_type, target_type, target_shopify_id, target_url, target_title, previous_state, proposed_change, reasoning)
             VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *`,
            [connection.id, actionType, candidate.type, candidate.id, candidate.url, candidate.title,
             JSON.stringify({ metaTitle: candidate.metaTitle, metaDescription: candidate.metaDescription }),
             JSON.stringify(proposedChange), p.reasoning || null]
          );
          const savedAction = inserted.rows[0];
          if (SHOPIFY_AUTO_APPLY_ACTIONS.has(actionType) && await shopifyAutoApplyAllowed(connection)) {
            const exec = await executeShopifyAction(savedAction, connection, accessToken);
            if (exec.executed) {
              await pool.query(`UPDATE shopify_actions SET approval_status = 'approved', execution_status = 'executed', auto_applied = TRUE, reviewed_at = NOW() WHERE id = $1`, [savedAction.id]);
              autoApplied.push(savedAction);
            } else {
              // A failed auto-apply stays pending so it shows up for approval, rather than vanishing.
              proposalsCreated.push(savedAction);
            }
          } else {
            proposalsCreated.push(savedAction);
          }
        }
      }
    } catch (e) { console.error('Shopify meta proposal generation failed:', e.message); }
  }

  // Real, deliberate real broken-link check — reuses the exact same real
  // extraction and real verification already proven for WordPress, on
  // Shopify's own real body_html.
  for (const item of items) {
    if (!item.bodyHtml) continue;
    const links = extractLinksFromHtml(item.bodyHtml, auditStoreUrl);
    const internalLinks = links.filter(l => l.isInternal);
    for (const link of internalLinks) {
      // checked as a full address: a relative link (/pages/about) is resolved against the store first, because as written it can never be fetched
      const address = resolveInternalLinkUrl(link.url, auditStoreUrl);
      if (!address) continue;
      const check = await checkInternalLinkResolves(address);
      if (!check.broken) continue;
      foundIssues.brokenLinks++;

      const existing = await pool.query(
        `SELECT id FROM shopify_actions WHERE shopify_connection_id = $1 AND target_shopify_id = $2 AND action_type = 'remove_broken_link' AND proposed_change->>'brokenUrl' = $3 AND approval_status = 'pending'`,
        [connection.id, item.id, link.url]
      );
      if (existing.rows.length) continue;

      const inserted = await pool.query(
        `INSERT INTO shopify_actions (shopify_connection_id, action_type, target_type, target_shopify_id, target_url, target_title, previous_state, proposed_change, reasoning)
         VALUES ($1,'remove_broken_link',$2,$3,$4,$5,$6,$7,$8) RETURNING *`,
        [connection.id, item.type, item.id, item.url, item.title,
         JSON.stringify({ linkText: link.text }),
         JSON.stringify({ brokenUrl: link.url }),
         `This link to ${link.url} no longer resolves.`]
      );
      proposalsCreated.push(inserted.rows[0]);
    }
  }

  return { foundIssues, proposalsCreated, autoApplied, analyzedCount: items.length };
}

async function generateShopifyBlogPostContent(context, topic, existingTitles, internalCandidates = []) {
  let externalCandidates = [];
  try {
    const results = await researchSearch(topic, { maxResults: 6 });
    const checks = await Promise.all(results.map(async (r) => ({ ...r, resolves: !(await checkInternalLinkResolves(r.url)).broken })));
    externalCandidates = checks.filter(c => c.resolves).map(c => ({ title: c.title, url: c.url })).slice(0, 4);
  } catch (e) { /* Real, deliberate graceful degradation — a post can still be written without real external links if research fails. */ }

  let reciprocalCandidate = null;
  if (context?.business?.id) {
    try { reciprocalCandidate = await findReciprocalLinkPartner(context.business.id, topic); } catch (e) { /* Real, deliberate no-op. */ }
    if (reciprocalCandidate) externalCandidates.push({ title: reciprocalCandidate.businessName, url: reciprocalCandidate.url });
  }

  const contextSummary = summarizeBusinessContextForAI(context) || 'No detailed context is available for this business yet.';
  const prompt = `You are a senior human copywriter and SEO/AEO/GEO strategist, ghostwriting a genuinely excellent, publication-ready blog post for a real Shopify store — the kind of post an actual industry expert would write, not something that reads as AI-generated.
${contextSummary}

TOPIC: ${topic}

REAL, EXISTING PAGES AND ARTICLES ON THIS STORE — you may ONLY link internally to these exact URLs, verbatim, never invent a new one:
${internalCandidates.length ? internalCandidates.map(c => `- "${c.title}" (${c.url})`).join('\n') : '(No real existing pages were found to link to.)'}

REAL, CURRENTLY-LIVE EXTERNAL PAGES relevant to this topic (confirmed reachable just now) — you may ONLY link externally to these exact URLs, verbatim, never invent a new one:
${externalCandidates.length ? externalCandidates.map(c => `- "${c.title}" (${c.url})`).join('\n') : '(No real, verified external sources were found — write without an external link rather than inventing one.)'}

REAL TITLES ALREADY PUBLISHED ON THIS STORE'S BLOG — do not substantially duplicate one of these:
${existingTitles.length ? existingTitles.map(t => `- ${t}`).join('\n') : '(No existing posts found.)'}

CRITICAL RULES:
1. NEVER invent or name a specific third-party business, company, or brand as an example unless it was explicitly named in the context above.
2. NEVER invent a fact, statistic, or specific claim about the business itself that isn't stated in the context above.
3. Do NOT create a "Further Reading" or similar closing link list — every internal or external link must be woven naturally into a sentence, inline, exactly where it adds real value, never listed separately, and never more than 3-4 links total in the whole post.
4. No checklist-with-checkmark-emoji summaries, no emoji at all, no meta-commentary about the post itself.
5. Punctuation must read as professionally edited: no em dashes or double hyphens as a stylistic device — use a period, comma, colon, or semicolon instead.
6. Choose ONE real, specific, valuable focus keyword for this topic. It must appear naturally in the title, meta title, meta description, and at least twice in the body.
7. Readability: short sentences (well under 20 words), short paragraphs (2-4 sentences), a new subheading every 2-4 paragraphs, plain everyday words, active voice, one idea per sentence.
8. Where it genuinely fits, include 1-2 short, natural question-and-answer moments for AI answer-engine citation.

Return ONLY valid JSON, no markdown, in exactly this structure:
{
  "title": "...",
  "metaTitle": "... (50-60 characters)",
  "metaDescription": "... (150-160 characters)",
  "focusKeyword": "...",
  "tags": ["2-4 relevant tag names"],
  "bodyHtml": "the full real HTML body as a single string, h2/h3 headings, paragraphs, a list only where genuinely clearest"
}`;

  const raw = await callAI({ persona: prompt, messages: [{ role: 'user', content: 'Write the blog post now, as JSON only.' }], complexity: 'complex', context: { feature: 'shopify_blog_post_generation' }, maxTokens: 6000 });
  const parsed = extractJSON(raw);
  if (!parsed.title || !parsed.bodyHtml) throw new Error('Could not generate this post — the response was missing required fields. Please try again.');

  const allVerifiedUrls = [...internalCandidates.map(c => c.url), ...externalCandidates.map(c => c.url)];
  const bodyHtml = stripUnverifiedLinks(parsed.bodyHtml, allVerifiedUrls).replace(/\s*[—–]\s*|\s+--\s+/g, ', ').replace(/,\s*,/g, ',').replace(/,\s*\./g, '.');

  return {
    title: parsed.title, metaTitle: parsed.metaTitle || parsed.title, metaDescription: parsed.metaDescription || '',
    focusKeyword: parsed.focusKeyword || '', tags: Array.isArray(parsed.tags) ? parsed.tags : [], bodyHtml,
    reciprocalCandidate,
  };
}

// Real, deliberate real Shopify API call — creates the real article, with
// real SEO metafields set in the same real request (Shopify supports this
// natively, unlike WordPress's separate follow-up meta write).
// Real, deliberate same conservative fix and same re-verification
// discipline as WordPress's execution path — never a guessed
// replacement URL, never touching anything but the one real, dead
// href, and a real re-fetch after saving to confirm it's genuinely
// gone rather than trusting the write call succeeded.
// Writes one SEO text field (title or description) on an article or page. If the field already has a value (as with a duplicate title) it is UPDATED; if not, it is created.
async function upsertShopifyMetafield(connection, accessToken, resourceType, ownerId, mf, ownerResource) {
  let existing = null;
  try {
    const list = await shopifyApiRequest(connection.shop_domain, accessToken, `/${resourceType}/${ownerId}/metafields.json`, { timeoutMs: 15000 });
    if (list.ok) existing = ((await list.json()).metafields || []).find(m => m.namespace === mf.namespace && m.key === mf.key) || null;
  } catch (e) { /* if the list cannot be read, creating it is the safe fallback */ }
  return existing
    ? shopifyApiRequest(connection.shop_domain, accessToken, `/metafields/${existing.id}.json`, { method: 'PUT', body: { metafield: { id: existing.id, value: mf.value, type: mf.type } }, timeoutMs: 15000 })
    : shopifyApiRequest(connection.shop_domain, accessToken, `/${resourceType}/${ownerId}/metafields.json`, { method: 'POST', body: { metafield: { ...mf, owner_id: ownerId, owner_resource: ownerResource } }, timeoutMs: 15000 });
}

async function executeShopifyAction(action, connection, accessToken) {
  const resourceType = action.target_type === 'post' ? 'articles' : 'pages';
  const change = action.proposed_change;

  try {
    if (SHOPIFY_ALT_TYPES.includes(action.action_type)) return await shopifyExecuteAltContent(action, connection, accessToken);
    if (SHOPIFY_INLINK_TYPES.includes(action.action_type)) return await shopifyExecuteInlink(action, connection, accessToken);
    if (SHOPIFY_CONTENT_TYPES.includes(action.action_type)) return await shopifyExecuteContentAction(action, connection, accessToken);
    if (action.action_type === 'add_tags') {
      // Tags are only ever ADDED: whatever the article already has is kept, in the same order. Reads the live tags right before writing.
      const articlePath = `/blogs/${connection.blog_id}/articles/${action.target_shopify_id}.json`;
      const readRes = await shopifyApiRequest(connection.shop_domain, accessToken, `${articlePath.replace('.json', '')}.json?fields=id,tags`, { timeoutMs: 15000 });
      if (!readRes.ok) return { executed: false, error: `Could not read this post's current tags (status ${readRes.status}).`, errorCode: 'tags_read_failed', errorParams: { status: readRes.status } };
      const current = String(((await readRes.json()).article || {}).tags || '').split(',').map(x => x.trim()).filter(Boolean);
      const wanted = (Array.isArray(change.tags) ? change.tags : []).map(x => String(x).trim()).filter(Boolean);
      if (!wanted.length) return { executed: false, error: 'No change to apply.', errorCode: 'tags_none' };
      const have = new Set(current.map(x => x.toLowerCase())), merged = [...current];
      for (const tag of wanted) if (!have.has(tag.toLowerCase())) { have.add(tag.toLowerCase()); merged.push(tag); }
      if (merged.length === current.length) return { executed: true, verified: true };   // they are all there already
      await pool.query('UPDATE shopify_actions SET previous_state = $1 WHERE id = $2', [JSON.stringify({ tags: current }), action.id]);
      const putRes = await shopifyApiRequest(connection.shop_domain, accessToken, articlePath, { method: 'PUT', body: { article: { id: action.target_shopify_id, tags: merged.join(', ') } }, timeoutMs: 15000 });
      if (!putRes.ok) return { executed: false, error: `Shopify rejected saving these tags (status ${putRes.status}).`, errorCode: 'tags_save_rejected', errorParams: { status: putRes.status } };
      const check = await shopifyApiRequest(connection.shop_domain, accessToken, `${articlePath.replace('.json', '')}.json?fields=id,tags`, { timeoutMs: 15000 });
      if (!check.ok) return { executed: true, verified: false, error: 'The tags were saved, but verification could not confirm them.', errorCode: 'tags_verify_unconfirmed' };
      const now = new Set(String(((await check.json()).article || {}).tags || '').split(',').map(x => x.trim().toLowerCase()));
      return wanted.every(tag => now.has(tag.toLowerCase())) ? { executed: true, verified: true } : { executed: true, verified: false, error: 'The tags were saved, but Shopify does not show them on the post yet.', errorCode: 'tags_verify_missing' };
    }
    if (change.oldUrl && change.newUrl) {
      // Changes only the address of the one link, keeping its text and the rest of the tag. Reads the page's current content right before editing.
      const readRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/${resourceType}/${action.target_shopify_id}.json?fields=body_html`);
      if (!readRes.ok) return { executed: false, error: `Could not read this page's current content (status ${readRes.status}).` };
      const current = await readRes.json(), currentHtml = current.article?.body_html ?? current.page?.body_html ?? '';
      const updatedHtml = replaceHrefInHtml(currentHtml, change.oldUrl, change.newUrl);
      if (updatedHtml === null) return { executed: false, error: 'This link is no longer present in the current content: it may have already been fixed or the content has changed.' };
      await saveLinkBackup(action.id, currentHtml, updatedHtml, SHOPIFY_LINK_SPEC);
      const bodyKey = action.target_type === 'post' ? 'article' : 'page';
      const updateRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/${resourceType}/${action.target_shopify_id}.json`, { method: 'PUT', body: { [bodyKey]: { id: action.target_shopify_id, body_html: updatedHtml } }, timeoutMs: 20000 });
      if (!updateRes.ok) return { executed: false, error: `Shopify rejected saving this change (status ${updateRes.status}).` };
      const verifyRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/${resourceType}/${action.target_shopify_id}.json?fields=body_html`);
      if (!verifyRes.ok) return { executed: true, verified: false, error: 'The change was saved, but verification could not confirm it.' };
      const verifyData = await verifyRes.json(), verifyHtml = verifyData.article?.body_html ?? verifyData.page?.body_html ?? '';
      await refreshLinkBackupHash(action.id, verifyHtml, SHOPIFY_LINK_SPEC);
      return verifyHtml.includes(`href="${change.newUrl}"`) || verifyHtml.includes(`href='${change.newUrl}'`) || verifyHtml.includes(change.newUrl.replace(/&/g, '&amp;')) ? { executed: true, verified: true } : { executed: true, verified: false, error: 'The change was saved, but the new address could not be confirmed in the page.' };
    }
    if (change.brokenUrl) {
      const readRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/${resourceType}/${action.target_shopify_id}.json?fields=body_html`);
      if (!readRes.ok) return { executed: false, error: `Could not read this page's current content (status ${readRes.status}).` };
      const current = await readRes.json();
      const currentHtml = current.article?.body_html ?? current.page?.body_html ?? '';

      const linkPattern = new RegExp(`<a\\s+[^>]*href=["']${change.brokenUrl.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}["'][^>]*>(.*?)<\\/a>`, 'gis');
      if (!linkPattern.test(currentHtml)) {
        return { executed: false, error: 'This link is no longer present in the current content — it may have already been fixed or the content has changed.' };
      }
      linkPattern.lastIndex = 0;
      const updatedHtml = currentHtml.replace(linkPattern, (match, innerText) => innerText);
      await saveLinkBackup(action.id, currentHtml, updatedHtml, SHOPIFY_LINK_SPEC);

      const bodyKey = action.target_type === 'post' ? 'article' : 'page';
      const updateRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/${resourceType}/${action.target_shopify_id}.json`, {
        method: 'PUT', body: { [bodyKey]: { id: action.target_shopify_id, body_html: updatedHtml } }, timeoutMs: 20000,
      });
      if (!updateRes.ok) return { executed: false, error: `Shopify rejected saving this change (status ${updateRes.status}).` };

      const verifyRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/${resourceType}/${action.target_shopify_id}.json?fields=body_html`);
      if (!verifyRes.ok) return { executed: true, verified: false, error: 'The change was saved, but verification could not confirm it.' };
      const verifyData = await verifyRes.json();
      const verifyHtml = verifyData.article?.body_html ?? verifyData.page?.body_html ?? '';
      await refreshLinkBackupHash(action.id, verifyHtml, SHOPIFY_LINK_SPEC);
      if (!verifyHtml.includes(change.brokenUrl)) return { executed: true, verified: true };
      return { executed: true, verified: false, error: 'The change was saved, but the broken link still appears to be present.' };
    }

    if (change.imagePrompt) {
      // A featured image for a blog article (a Shopify page has none). The picture is the preview if there is one, otherwise it is made now.
      if (action.target_type !== 'post') return { executed: false, error: 'Shopify pages do not have a featured image: only blog articles do.' };
      if (!connection.blog_id) return { executed: false, error: 'No blog was found on this Shopify store.' };
      const stored = await loadFeaturedPreview('shopify', action.id); let buffer;
      if (stored) buffer = stored.png;
      else {
        const allow = await usageAllowance(await businessOwnerId(connection.business_id), 'images'); if (!allow.ok) return { executed: false, error: allow.message };
        try { buffer = await generateAIImage(change.imagePrompt); }
        catch (e) { console.error('Featured image generation failed:', e.message); return { executed: false, error: 'The image service could not create the picture right now. Please try again in a moment.' }; }
        await logFeaturedGeneration(connection.business_id, 'shopify', 'apply');
      }
      const articlePath = `/blogs/${connection.blog_id}/articles/${action.target_shopify_id}.json`;
      const putRes = await shopifyApiRequest(connection.shop_domain, accessToken, articlePath, { method: 'PUT', body: { article: { id: action.target_shopify_id, image: { attachment: buffer.toString('base64'), alt: change.altText || '' } } }, timeoutMs: 60000 });
      if (!putRes.ok) return { executed: false, error: `Shopify rejected saving the image (status ${putRes.status}).` };
      const check = await shopifyApiRequest(connection.shop_domain, accessToken, `${articlePath}?fields=id,image`);
      if (!check.ok) return { executed: true, verified: false, error: 'The image was saved, but verification could not confirm it.' };
      const img = ((await check.json()).article || {}).image;
      if (!img || !img.src) return { executed: true, verified: false, error: 'The image was saved, but Shopify does not show it on the article yet.' };
      await recordFeaturedApplied(FEATURED_SPECS.shopify, action.id, { appliedImageSrc: img.src }); await dropFeaturedPreview('shopify', action.id);
      return { executed: true, verified: true };
    }

    // Real, deliberate single metafields write for the meta-tag action
    // types — the same real namespace/key pair the bridge's own
    // generated-content flow already uses, so a fix here reads back
    // correctly everywhere else that checks these same real fields.
    const metafields = [];
    if (change.metaTitle) metafields.push({ namespace: 'global', key: 'title_tag', value: change.metaTitle, type: 'single_line_text_field' });
    if (change.metaDescription) metafields.push({ namespace: 'global', key: 'description_tag', value: change.metaDescription, type: 'single_line_text_field' });
    if (!metafields.length) return { executed: false, error: 'No change to apply.' };

    for (const mf of metafields) {
      const res = await upsertShopifyMetafield(connection, accessToken, resourceType, action.target_shopify_id, mf, action.target_type === 'post' ? 'article' : 'page');
      if (!res.ok) return { executed: false, error: `Shopify rejected saving this change (status ${res.status}).`, errorCode: 'meta_save_rejected', errorParams: { status: res.status } };
    }
    return { executed: true, verified: true };
  } catch (e) {
    return { executed: false, error: safeErrorMessage(e, 'An unexpected error occurred while applying this change.') };
  }
}

async function createShopifyBlogPost(connection, accessToken, postData) {
  const { title, bodyHtml, metaTitle, metaDescription, tags, status } = postData;
  if (!connection.blog_id) return { success: false, error: 'No blog was found on this Shopify store to publish to.' };

  const createRes = await shopifyApiRequest(connection.shop_domain, accessToken, `/blogs/${connection.blog_id}/articles.json`, {
    method: 'POST',
    body: {
      article: {
        title, body_html: bodyHtml, tags: (tags || []).join(', '), published: status === 'publish',
        metafields: [
          ...(metaTitle ? [{ namespace: 'global', key: 'title_tag', value: metaTitle, type: 'single_line_text_field' }] : []),
          ...(metaDescription ? [{ namespace: 'global', key: 'description_tag', value: metaDescription, type: 'single_line_text_field' }] : []),
        ],
      },
    },
    timeoutMs: 20000,
  });
  if (!createRes.ok) {
    let detail = null;
    try { detail = await createRes.json(); } catch { /* Real, deliberate no-op. */ }
    return { success: false, error: detail?.errors ? JSON.stringify(detail.errors) : `Shopify rejected creating this post (status ${createRes.status}).` };
  }
  const created = await createRes.json();
  const article = created.article;
  return { success: true, id: article.id, handle: article.handle, status: article.published ? 'publish' : 'draft', url: `${await getShopifyStoreUrl(connection, accessToken)}/blogs/${await getShopifyBlogHandle(connection, accessToken)}/${article.handle}` };
}

app.get('/api/business/:id/reciprocal-network', authRequired, async (req, res) => {
  try {
    const account = await resolveAccount(req.userId);
    const biz = await pool.query('SELECT id FROM businesses WHERE id = $1 AND user_id = $2', [req.params.id, account.id]);
    if (!biz.rows.length) return res.status(404).json({ error: 'Business not found' });

    const optInResult = await pool.query('SELECT opted_in, opted_in_at FROM reciprocal_network_opt_ins WHERE business_id = $1', [req.params.id]);
    const linksGiven = await pool.query(
      `SELECT rl.*, b.name AS to_business_name FROM reciprocal_links_placed rl JOIN businesses b ON b.id = rl.to_business_id WHERE rl.from_business_id = $1 ORDER BY rl.placed_at DESC`,
      [req.params.id]
    );
    const linksReceived = await pool.query(
      `SELECT rl.*, b.name AS from_business_name FROM reciprocal_links_placed rl JOIN businesses b ON b.id = rl.from_business_id WHERE rl.to_business_id = $1 ORDER BY rl.placed_at DESC`,
      [req.params.id]
    );

    // Real, deliberate platform-wide count, shown to a business before it
    // ever opts in — a real trust signal ("this is a real, active network
    // of N real businesses"), not a guess or a marketing number.
    const networkSize = await pool.query(`SELECT COUNT(*) FROM reciprocal_network_opt_ins WHERE opted_in = TRUE`);

    res.json({
      optedIn: optInResult.rows[0]?.opted_in || false,
      optedInAt: optInResult.rows[0]?.opted_in_at || null,
      linksGiven: linksGiven.rows,
      linksReceived: linksReceived.rows,
      networkSize: Number(networkSize.rows[0].count),
    });
  } catch (e) {
    console.error('Get reciprocal network status error:', e.message);
    res.status(500).json({ error: 'Could not load reciprocal network status.' });
  }
});

app.post('/api/business/:id/reciprocal-network/opt-in', authRequired, async (req, res) => {
  try {
    const account = await resolveAccount(req.userId);
    const biz = await pool.query('SELECT id, website FROM businesses WHERE id = $1 AND user_id = $2', [req.params.id, account.id]);
    if (!biz.rows.length) return res.status(404).json({ error: 'Business not found' });
    const resolvedSiteUrl = await resolveBusinessSiteUrl(req.params.id, biz.rows[0].website);
    if (!resolvedSiteUrl) return res.status(400).json({ error: 'A website URL is required before opting into the reciprocal network — add one on the business profile, or connect WordPress or Shopify first.' });

    await pool.query(
      `INSERT INTO reciprocal_network_opt_ins (business_id, opted_in, opted_in_at, updated_at)
       VALUES ($1, TRUE, NOW(), NOW())
       ON CONFLICT (business_id) DO UPDATE SET opted_in = TRUE, opted_in_at = NOW(), updated_at = NOW()`,
      [req.params.id]
    );
    res.json({ success: true });
  } catch (e) {
    console.error('Opt in to reciprocal network error:', e.message);
    res.status(500).json({ error: 'Could not opt in. Please try again.' });
  }
});

app.post('/api/business/:id/reciprocal-network/opt-out', authRequired, async (req, res) => {
  try {
    const account = await resolveAccount(req.userId);
    const biz = await pool.query('SELECT id FROM businesses WHERE id = $1 AND user_id = $2', [req.params.id, account.id]);
    if (!biz.rows.length) return res.status(404).json({ error: 'Business not found' });

    // Real, deliberate update-in-place rather than delete — opting out
    // stops any new real matching immediately, but the real history of
    // links already placed stays intact and visible, since those real
    // links still genuinely exist on real, live pages regardless of this
    // business's current real preference.
    await pool.query(
      `UPDATE reciprocal_network_opt_ins SET opted_in = FALSE, updated_at = NOW() WHERE business_id = $1`,
      [req.params.id]
    );
    res.json({ success: true });
  } catch (e) {
    console.error('Opt out of reciprocal network error:', e.message);
    res.status(500).json({ error: 'Could not opt out. Please try again.' });
  }
});

app.post('/api/business/:id/reciprocal-network/report/:placementId', authRequired, async (req, res) => {
  try {
    const account = await resolveAccount(req.userId);
    const biz = await pool.query('SELECT id, name FROM businesses WHERE id = $1 AND user_id = $2', [req.params.id, account.id]);
    if (!biz.rows.length) return res.status(404).json({ error: 'Business not found' });

    // Real, deliberate authorization check — only a real party to this
    // exact placement (the one that gave the link or the one that
    // received it) can report it, never an arbitrary business guessing
    // at another placement's id.
    const placement = await pool.query(
      `SELECT * FROM reciprocal_links_placed WHERE id = $1 AND (from_business_id = $2 OR to_business_id = $2)`,
      [req.params.placementId, req.params.id]
    );
    if (!placement.rows.length) return res.status(404).json({ error: 'Placement not found' });

    const reason = (req.body?.reason || '').trim().slice(0, 1000);
    await pool.query(
      `INSERT INTO reciprocal_link_reports (placement_id, reported_by_business_id, reason) VALUES ($1, $2, $3)`,
      [req.params.placementId, req.params.id, reason || null]
    );

    // Real, deliberate admin notification — the same real email path
    // already used for payment submissions, so a real report never just
    // sits silently in a table waiting to be noticed by chance.
    try {
      await sendEmail(ADMIN_EMAIL, `Partner Network report — ${biz.rows[0].name}`,
        `<p><strong>${biz.rows[0].name}</strong> reported a Partner Network placement.</p>
         <p><strong>Reason:</strong> ${reason || '(no reason given)'}</p>
         <p><strong>Placement:</strong> ${placement.rows[0].from_post_url || placement.rows[0].id}</p>`);
    } catch (e) { /* Real, deliberate no-op — the report itself is already saved; a notification email failing shouldn't fail the whole request. */ }

    res.json({ success: true });
  } catch (e) {
    console.error('Report placement error:', e.message);
    res.status(500).json({ error: 'Could not submit this report. Please try again.' });
  }
});

app.post('/api/business/:id/backlinks/search', authRequired, async (req, res) => {
  try {
    const account = await resolveAccount(req.userId);
    const context = await getBusinessContext(req.params.id, account.id);
    if (!context) return res.status(404).json({ error: 'Business not found' });

    const siteUrl = await resolveBusinessSiteUrl(req.params.id, context.business.website);
    if (!siteUrl) return res.status(400).json({ error: 'This business needs a website URL — add one on the business profile, or connect WordPress or Shopify first.' });

    const opportunities = await findBacklinkOpportunities(context, siteUrl);

    // Real, deliberate ignore-on-conflict insert — the same real
    // opportunity found again on a later search shouldn't duplicate or
    // reset a status the person may have already updated (e.g. marked
    // "contacted").
    let insertedCount = 0;
    for (const opp of opportunities) {
      const result = await pool.query(
        `INSERT INTO backlink_opportunities (business_id, opportunity_type, title, url, description, contact_email)
         VALUES ($1, $2, $3, $4, $5, $6) ON CONFLICT (business_id, url) DO NOTHING RETURNING id`,
        [req.params.id, opp.type, opp.title, opp.url, opp.description, opp.contactEmail || null]
      );
      if (result.rows.length) insertedCount++;
    }

    res.json({ success: true, foundCount: opportunities.length, newCount: insertedCount });
  } catch (err) {
    console.error('Backlink search error:', err.message);
    res.status(500).json({ error: safeErrorMessage(err, 'Failed to search for backlink opportunities. Please try again.') });
  }
});

