  const r = await pool.query(`UPDATE contact_messages SET status = $2::varchar, handled_at = CASE WHEN $2::varchar = 'handled' THEN NOW() ELSE NULL END WHERE id = $1 RETURNING id`, [id, status === 'handled' ? 'handled' : 'new']);
