  const lockedA = rateCount(kA, LOGIN_WINDOW) >= ADMIN_2FA_MAX_PER_ADMIN, lockedI = ip !== 'unknown' && rateCount(kI, LOGIN_WINDOW) >= ADMIN_2FA_MAX_PER_IP;
